def convert_measurements(measurements, unit):
    meters = []
    feet = []
    for val in measurements:
        if unit == 'km':
            m = val * 1000
        elif unit == 'cm':
            m = val / 100
        elif unit == 'mm':
            m = val / 1000
        elif unit == 'm':
            m = val
        else:
            m = val
        f = m * 3.28084
        meters.append(m)
        feet.append(f)
    return meters, feet

