        calculate_bmi("70")
    except InvalidWeightType as e:
        print(e)
    try:
        calculate_bmi(-5)
    except InvalidWeightValue as e:
        print(e)
    try:
        calculate_bmi(600)
    except InvalidWeightValue as e:
        print(e)
    try:
        calculate_bmi(True)
    except InvalidWeightType as e:
        print(e)

