import os

def calculate_total_volume(file_path: str) -> float:
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    total_volume = 0.0
    with open(file_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                volume = float(line)
                total_volume += volume
            except ValueError:
                continue
    return total_volume

