class VolumeCalculator:
    def __init__(self):
        self.volumes = []

    def read_volumes(self, file_path):
        try:
            with open(file_path, 'r') as file:
                lines = file.readlines()
                self.volumes = []
                for line in lines:
                    line = line.strip()
                    if line:
                        try:
                            value = float(line)
                            self.volumes.append(value)
                        except ValueError:
                            continue
                return self.volumes
        except FileNotFoundError:
            return []
        except IOError:
            return []
        except Exception:
            return []

    def calculate_total(self):
        if not self.volumes:
            return 0.0
        total = 0.0
        for volume in self.volumes:
            total += volume
        return total

