def parse_volumes(volume_string):
    parts = volume_string.split(',')
    results = []
    errors = []
    for part in parts:
        stripped = part.strip()
        if stripped:
            try:
                results.append(float(stripped))
            except ValueError:
                errors.append(stripped)
    if errors:
        raise ValueError("Non-numeric values found: " + str(errors))
    return results

