class VolumeScaler:
    def __init__(self, factor):
        self.factor = factor

    def scale(self, volumes):
        return volumes * self.factor

    def compute_total_volume(self, volumes):
        return np.sum(volumes)

    def compute_average_volume(self, volumes):
        if volumes.size == 0:
            return 0.0
        return np.mean(volumes)

