        self._data[key] = volume

    def get_base(self, key):
        if key in self._data:
            return self._data[key]
        return 0

    def get_scaled(self, key, factor):
        if key in self._data:
            return self._data[key] * factor
        return 0

    def remove(self, key):
        if key in self._data:
            del self._data[key]
            return True
        return False

    def list_keys(self):
        return list(self._data.keys())

    def clear(self):
        self._data.clear()

