import csv
import os
import tempfile

def calculate_average_temperature(csv_file_path):
    if not os.path.exists(csv_file_path):
        raise FileNotFoundError(f"The file {csv_file_path} does not exist.")

    temperatures = []
    try:
        with open(csv_file_path, 'r') as file:
            reader = csv.reader(file)
            header = next(reader, None)
            if header is None:
                raise ValueError("The CSV file is empty.")

            temp_col_index = None
            for i, col_name in enumerate(header):
                if col_name.strip().lower() == 'temperature':
                    temp_col_index = i
                    break

            if temp_col_index is None:
                raise ValueError("The CSV file does not contain a 'temperature' column.")

            for row in reader:
                if len(row) > temp_col_index:
                    try:
                        temp_value = float(row[temp_col_index])
                        temperatures.append(temp_value)
                    except ValueError:
                        continue
    except IOError as e:
        raise IOError(f"Error reading file: {e}")

    if not temperatures:
        return 0.0

    return sum(temperatures) / len(temperatures)

def create_sample_csv(file_path):
    with open(file_path, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerow(['date', 'temperature', 'humidity'])
        writer.writerow(['2023-10-01', '22.5', '60'])
        writer.writerow(['2023-10-02', '23.1', '55'])
        writer.writerow(['2023-10-03', '21.8', '65'])
        writer.writerow(['2023-10-04', '24.0', '50'])
        writer.writerow(['2023-10-05', '23.5', '58'])

if __name__ == '__main__':
    with tempfile.NamedTemporaryFile(mode='w', suffix='.csv', delete=False) as temp_file:
        temp_path = temp_file.name
    create_sample_csv(temp_path)

    try:
        avg_temp = calculate_average_temperature(temp_path)
        print(avg_temp)
    finally:
        os.unlink(temp_path)

def convert_volumes_to_ml(volumes):
    result = []
    for v in volumes:
        if v == 0:
            result.append(0.0)
            continue
        if not isinstance(v, (int, float)):
            raise TypeError("Volume values must be numeric.")

        unit = str(v).lower().split(' ')[-1] if ' ' in str(v) else ''
        val = float(str(v).split(' ')[0]) if ' ' in str(v) else float(str(v))

        if val < 0:
            val = abs(val)

        if unit == 'liters' or unit == 'liter':
            converted = val * 1000.0
        elif unit == 'gallons' or unit == 'gallon':
            converted = val * 3785.41
        elif unit == 'cubic_inches' or unit == 'cubic_inch':
            converted = val * 16.387064
        else:
            if isinstance(v, tuple):
                val, unit = v
                if val < 0:
                    val = abs(val)
                if unit == 'liters' or unit == 'liter':
                    converted = val * 1000.0
                elif unit == 'gallons' or unit == 'gallon':
                    converted = val * 3785.41
                elif unit == 'cubic_inches' or unit == 'cubic_inch':
                    converted = val * 16.387064
                else:
                    raise ValueError(f"Unsupported unit: {unit}")
            else:
                raise ValueError(f"Unit must be specified for value: {v}")

        if v < 0:
            result.append(-converted)
        else:
            result.append(converted)
    return result

if __name__ == '__main__':
    samples = [
        (1.0, 'liters'),
        (2.5, 'gallons'),
        (100, 'cubic_inches'),
        (0, 'liters'),
        (-1.0, 'liters')
    ]
    print(convert_volumes_to_ml(samples))

