import csv
import io
import os

def calculate_average_temperature(file_path):
    temperatures = []
    with open(file_path, 'r', newline='') as csvfile:
        reader = csv.reader(csvfile)
        header = next(reader, None)
        if header is None:
            return None
        if not header:
            return None
        temp_idx = None
        for idx, col in enumerate(header):
            if col.lower().strip() in ['temperature', 'temp', 'celsius', 'fahrenheit']:
                temp_idx = idx
                break
        if temp_idx is None:
            raise ValueError("No temperature column found in CSV header")
        for row in reader:
            if not row:
                continue
            if len(row) <= temp_idx:
                continue
            val_str = row[temp_idx].strip()
            if not val_str:
                continue
            try:
                temp = float(val_str)
                temperatures.append(temp)
            except ValueError:
                continue
    if not temperatures:
        return None
    return sum(temperatures) / len(temperatures)

if __name__ == '__main__':
    temp_data = "timestamp,temperature,humidity\n2023-01-01 10:00,22.5,45\n2023-01-01 11:00,23.1,44\n2023-01-01 12:00,24.0,43\n2023-01-01 13:00,25.2,42"
    sample_csv_path = 'sample_temps.csv'
    with open(sample_csv_path, 'w', newline='') as f:
        f.write(temp_data)
    avg_temp = calculate_average_temperature(sample_csv_path)
    print(avg_temp)
    os.remove(sample_csv_path)

def convert_to_milliliters(volumes):
    factors = {
        'liters': 1000.0,
        'gallons': 3785.411784,
        'cubic_inches': 16.387064,
        'milliliters': 1.0
    }
    results = []
    for value, unit in volumes:
        if value < 0:
            results.append((abs(value), unit))
        elif value == 0:
            results.append((0.0, unit))
        else:
            factor = factors.get(unit)
            if factor is None:
                raise ValueError(f"Unsupported unit: {unit}")
            results.append((value * factor, 'milliliters'))
    return results

if __name__ == '__main__':
    sample_volumes = [
        (1.5, 'liters'),
        (2.0, 'gallons'),
        (10.0, 'cubic_inches'),
        (0.0, 'milliliters'),
        (-5.0, 'liters')
    ]
    converted = convert_to_milliliters(sample_volumes)
    for val, unit in converted:
        print(f"{val} {unit}")

import csv
import io

def calculate_average_temperature(file_content: str) -> float:
    if not file_content.strip():
        raise ValueError("File content is empty")

    reader = csv.DictReader(io.StringIO(file_content))
    temperatures = []

    for row in reader:
        try:
            temp_str = row.get('temperature')
            if temp_str is None:
                raise KeyError("temperature")
            temp = float(temp_str)
            temperatures.append(temp)
        except (ValueError, KeyError) as e:
            raise ValueError(f"Invalid temperature data: {e}")

    if not temperatures:
        raise ValueError("No valid temperature readings found")

    return sum(temperatures) / len(temperatures)

if __name__ == '__main__':
    sample_csv = """date,temperature
2023-01-01,20.5
2023-01-02,22.0
2023-01-03,19.5"""

    result = calculate_average_temperature(sample_csv)
    print(result)

def convert_to_milliliters(measurements):
    LITERS_TO_ML = 1000.0
    GALLONS_TO_ML = 3785.411784
    CUBIC_INCHES_TO_ML = 16.387064

    converted = []

    for item in measurements:
        value = item["value"]
        unit = item["unit"]

        if value < 0:
            raise ValueError("Volume measurements cannot be negative")

        if unit == "liters":
            result = value * LITERS_TO_ML
        elif unit == "gallons":
            result = value * GALLONS_TO_ML
        elif unit == "cubic_inches":
            result = value * CUBIC_INCHES_TO_ML
        else:
            raise ValueError(f"Unknown unit: {unit}")

        converted.append({"value": result, "unit": "milliliters"})

    return converted

if __name__ == '__main__':
    sample_data = [
        {"value": 1, "unit": "liters"},
        {"value": 2, "unit": "gallons"},
        {"value": 100, "unit": "cubic_inches"},
        {"value": 0, "unit": "liters"}
    ]

    results = convert_to_milliliters(sample_data)
    print(results)

import csv
import tempfile
import os

class TemperatureAnalyzer:
    def __init__(self):
        self.readings = []

    def load_from_file(self, file_path):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")
        self.readings = []
        try:
            with open(file_path, 'r', newline='', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                if 'temperature' not in reader.fieldnames:
                    raise ValueError("CSV must contain 'temperature' column")
                for row in reader:
                    try:
                        val = float(row['temperature'])
                        self.readings.append(val)
                    except ValueError:
                        continue
        except IOError as e:
            raise IOError(f"Error reading file: {e}")

        if not self.readings:
            raise ValueError("No valid temperature readings could be parsed from the file.")

    def calculate_average(self):
        if not self.readings:
            return 0.0
        return sum(self.readings) / len(self.readings)

    def get_reading_count(self):
        return len(self.readings)

def create_sample_data():
    fd, path = tempfile.mkstemp(suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['date', 'temperature', 'location'])
            writer.writerow(['2023-10-01', '20.5', 'A'])
            writer.writerow(['2023-10-02', '22.0', 'B'])
            writer.writerow(['2023-10-03', '19.5', 'C'])
            writer.writerow(['2023-10-04', 'invalid', 'D'])
            writer.writerow(['2023-10-05', '21.0', 'E'])
        return path
    except Exception:
        os.close(fd)
        raise

if __name__ == '__main__':
    temp_file_path = create_sample_data()
    analyzer = TemperatureAnalyzer()
    try:
        analyzer.load_from_file(temp_file_path)
        count = analyzer.get_reading_count()
        average = analyzer.calculate_average()
        print(f"Count: {count}")
        print(f"Average: {average}")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        if os.path.exists(temp_file_path):
            os.remove(temp_file_path)

