    result = calculate_average_temperature(sample_readings)
    print(result)

import csv
import tempfile
import os

def calculate_average_temperature(filepath):
    try:
        with open(filepath, 'r', newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            temperatures = []
            for row in reader:
                try:
                    temp = float(row['temperature'])
                    temperatures.append(temp)
                except (KeyError, ValueError):
                    continue
            if not temperatures:
                return None
            return sum(temperatures) / len(temperatures)
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {filepath} was not found.")
    except Exception as e:
        raise e

def create_sample_csv():
    fd, temp_path = tempfile.mkstemp(suffix='.csv')
    with os.fdopen(fd, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['timestamp', 'temperature', 'humidity'])
        writer.writerow(['2023-10-01 00:00:00', '22.5', '45'])
        writer.writerow(['2023-10-01 01:00:00', '21.8', '46'])
        writer.writerow(['2023-10-01 02:00:00', '23.1', '44'])
    return temp_path

if __name__ == '__main__':
    sample_file = create_sample_csv()
    average = calculate_average_temperature(sample_file)
    print(average)
    os.remove(sample_file)

import csv
import os
import tempfile
import statistics

def read_and_average_temperatures(file_path):
    temperatures = []
    try:
        with open(file_path, mode='r', newline='', encoding='utf-8') as file:
            reader = csv.reader(file)
            for row in reader:
                if len(row) >= 1 and row[0].strip():
                    try:
                        value = float(row[0].strip())
                        temperatures.append(value)
                    except ValueError:
                        continue
        if not temperatures:
            return 0.0
        return statistics.mean(temperatures)
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path}")
    except PermissionError:
        raise PermissionError(f"Permission denied: {file_path}")
    except csv.Error as e:
        raise RuntimeError(f"CSV parsing error: {e}")

if __name__ == '__main__':
    sample_content = "20.5\n21.3\n19.8\n22.1\n20.0"
    temp_file_path = os.path.join(tempfile.gettempdir(), 'sample_temp_data.csv')
    with open(temp_file_path, 'w', encoding='utf-8') as f:
        f.write(sample_content)
    try:
        result = read_and_average_temperatures(temp_file_path)
        print(f"{result:.2f}")
    finally:
        if os.path.exists(temp_file_path):
            os.remove(temp_file_path)

import csv
import tempfile
import os

def calculate_average_temperature(csv_file_path):
    try:
        with open(csv_file_path, 'r', newline='') as file:
            reader = csv.reader(file)
            header = next(reader, None)
            if header is None:
                return None
            temperature_index = None
            for idx, col_name in enumerate(header):
                if 'temperature' in col_name.lower():
                    temperature_index = idx
                    break
            if temperature_index is None:
                return None
            temperatures = []
            for row in reader:
                if len(row) > temperature_index:
                    try:
                        temp_value = float(row[temperature_index])
                        temperatures.append(temp_value)
                    except ValueError:
                        continue
            if not temperatures:
                return None
            average = sum(temperatures) / len(temperatures)
            return average
    except FileNotFoundError:
        return None
    except Exception:
        return None
