def convert_weight(value, from_unit, to_unit):
    weights = {
        'kilogram': 1,
        'gram': 0.001,
        'milligram': 0.000001,
        'pound': 0.45359237,
        'ounce': 0.028349523125
    }
    if from_unit not in weights or to_unit not in weights:
