        'mm': 0.001,
        'mi': 1609.344,
        'ft': 0.3048,
        'in': 0.0254,
        'yd': 0.9144,
    }

    if target_unit not in conversion_factors:
        raise ValueError(f"Unsupported unit: {target_unit}")

    if target_unit == 'm':
        return distance
    else:
        meters = distance / conversion_factors[target_unit]
        return meters

