        if to_unit not in self.to_meters:
            raise ValueError(f"Unsupported target unit: {to_unit}")
        if value < 0:
            raise ValueError("Distance cannot be negative")
        meters = value * self.to_meters[from_unit]
        result = meters / self.to_meters[to_unit]
        return result

