    print(normalize_to_meters(100, 'cm'))
    print(normalize_to_meters(5, 'mi'))
    print(normalize_to_meters(12, 'in'))
    print(normalize_to_meters(1, 'm'))
    print(normalize_to_meters(1000, 'nm'))

import unittest

class DistanceConverter:
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit

    def to_meters(self):
        if self.unit == "m":
            return self.value
        if self.unit == "km":
            return self.value * 1000.0
        if self.unit == "cm":
            return self.value / 100.0
        if self.unit == "mm":
            return self.value / 1000.0
        if self.unit == "mi":
            return self.value * 1609.34
        if self.unit == "yd":
            return self.value * 0.9144
        if self.unit == "ft":
            return self.value * 0.3048
        if self.unit == "in":
            return self.value * 0.0254
        raise ValueError(f"Unknown unit: {self.unit}")

    def to_kilometers(self):
        return self.to_meters() / 1000.0

    def to_centimeters(self):
        return self.to_meters() * 100.0

    def to_millimeters(self):
        return self.to_meters() * 1000.0

    def to_miles(self):
        return self.to_meters() / 1609.34

    def to_yards(self):
        return self.to_meters() / 0.9144

    def to_feet(self):
        return self.to_meters() / 0.3048

    def to_inches(self):
        return self.to_meters() / 0.0254

    def convert(self, target_unit):
        target_methods = {
            "m": self.to_meters,
            "km": self.to_kilometers,
            "cm": self.to_centimeters,
            "mm": self.to_millimeters,
            "mi": self.to_miles,
            "yd": self.to_yards,
            "ft": self.to_feet,
            "in": self.to_inches
        }
        if target_unit not in target_methods:
            raise ValueError(f"Unknown target unit: {target_unit}")
        return target_methods[target_unit]()

