import math

def normalize_to_meters(value: float, unit: str) -> float:
    value = float(value)
    unit = unit.lower().strip()
    conversion_factors = {'m': 1.0, 'km': 1000.0, 'cm': 0.01, 'mm': 0.001, 'mi': 1609.344, 'ft': 0.3048, 'in': 0.0254, 'yd': 0.9144}
    if unit not in conversion_factors:
        raise ValueError(f'Unsupported unit: {unit}')
    return value * conversion_factors[unit]

def format_distance(meters: float, precision: int=2) -> str:
    meters = float(meters)
    if abs(meters) < 0.001:
        return f'{meters * 1000:.{precision}f} mm'
    elif abs(meters) < 1:
        return f'{meters * 100:.{precision}f} cm'
    elif abs(meters) < 1000:
        return f'{meters:.{precision}f} m'
    else:
        return f'{meters / 1000:.{precision}f} km'
if __name__ == '__main__':
    samples = [(5.0, 'km'), (150.0, 'cm'), (0.005, 'km'), (3.28, 'ft'), (1.0, 'in'), (10000.0, 'mm')]
    for val, unit in samples:
        meters = normalize_to_meters(val, unit)
        formatted = format_distance(meters)
        print(f'{val} {unit} = {meters} m -> {formatted}')

import unittest
import math

class DistanceConverter:
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit

    def convert_to(self, target_unit):
        if self.unit == target_unit:
            return self.value
        if self.unit == 'meters':
            return self._from_meters(target_unit)
        if self.unit == 'kilometers':
            return self._from_kilometers(target_unit)
        if self.unit == 'miles':
            return self._from_miles(target_unit)
        if self.unit == 'feet':
            return self._from_feet(target_unit)
        raise ValueError(f"Unsupported unit: {self.unit}")

    def _to_meters(self):
        if self.unit == 'meters':
            return self.value
        if self.unit == 'kilometers':
            return self.value * 1000
        if self.unit == 'miles':
            return self.value * 1609.344
        if self.unit == 'feet':
            return self.value / 3.28084
        raise ValueError(f"Unsupported unit: {self.unit}")

    def _from_meters(self, target_unit):
        if target_unit == 'meters':
            return self.value
        if target_unit == 'kilometers':
            return self.value / 1000
        if target_unit == 'miles':
            return self.value / 1609.344
        if target_unit == 'feet':
            return self.value * 3.28084
        raise ValueError(f"Unsupported target unit: {target_unit}")

    def _from_kilometers(self, target_unit):
        meters = self.value * 1000
        return self._from_meters(target_unit)

    def _from_miles(self, target_unit):
        meters = self.value * 1609.344
        return self._from_meters(target_unit)

    def _from_feet(self, target_unit):
        meters = self.value / 3.28084
        return self._from_meters(target_unit)

