def convert_to_appropriate_unit(total_seconds):
    if total_seconds >= 3600:
        return total_seconds / 3600, "hours"
    elif total_seconds >= 60:
        return total_seconds / 60, "minutes"
    else:
        return total_seconds, "seconds"

