import math

SECONDS_IN_MINUTE = 60
SECONDS_IN_HOUR = 3600
SECONDS_IN_DAY = 86400
SECONDS_IN_YEAR = 31557600
SECONDS_IN_MONTH = 2629800

def convert(source_value, source_unit, target_unit):
    source_unit = source_unit.lower()
    target_unit = target_unit.lower()
    valid_units = ['year', 'month', 'day', 'hour', 'minute', 'second']

    if source_unit not in valid_units or target_unit not in valid_units:
        raise ValueError(f"Invalid unit. Valid units are: {', '.join(valid_units)}")

    if source_unit == 'year':
        seconds = source_value * SECONDS_IN_YEAR
    elif source_unit == 'month':
        seconds = source_value * SECONDS_IN_MONTH
    elif source_unit == 'day':
        seconds = source_value * SECONDS_IN_DAY
    elif source_unit == 'hour':
        seconds = source_value * SECONDS_IN_HOUR
    elif source_unit == 'minute':
        seconds = source_value * SECONDS_IN_MINUTE
    else:
        seconds = source_value

    if target_unit == 'year':
        return seconds / SECONDS_IN_YEAR
    elif target_unit == 'month':
        return seconds / SECONDS_IN_MONTH
    elif target_unit == 'day':
        return seconds / SECONDS_IN_DAY
    elif target_unit == 'hour':
        return seconds / SECONDS_IN_HOUR
    elif target_unit == 'minute':
        return seconds / SECONDS_IN_MINUTE
    else:
        return seconds

class TimeConverter:
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit.lower()

    def to(self, target_unit):
        return convert(self.value, self.unit, target_unit)

    def to_all(self):
        units = ['year', 'month', 'day', 'hour', 'minute', 'second']
        results = {}
        for unit in units:
            results[unit] = convert(self.value, self.unit, unit)
        return results

if __name__ == '__main__':
    sample_value = 2
    sample_unit = 'years'
    target_unit = 'days'

    direct_result = convert(sample_value, sample_unit, target_unit)
    print(f"{sample_value} {sample_unit} is {direct_result} {target_unit}")

    converter = TimeConverter(1, 'hour')
    minute_result = converter.to('minute')
    print(f"1 hour is {minute_result} minutes")

    all_conversions = converter.to_all()
    print(f"1 hour in all units: {all_conversions}")

import unittest

def seconds_to_hms(total_seconds):
    if not isinstance(total_seconds, (int, float)):
        raise TypeError("Input must be a number")
    if total_seconds < 0:
        raise ValueError("Input must be non-negative")

    total_seconds = int(total_seconds)
    hours = total_seconds // 3600
    remaining_seconds = total_seconds % 3600
    minutes = remaining_seconds // 60
    seconds = remaining_seconds % 60
    return (hours, minutes, seconds)

def hms_to_seconds(hours, minutes, seconds):
    if not all(isinstance(x, (int, float)) for x in [hours, minutes, seconds]):
        raise TypeError("All inputs must be numbers")
    if any(x < 0 for x in [hours, minutes, seconds]):
        raise ValueError("All inputs must be non-negative")

    return hours * 3600 + minutes * 60 + seconds

class TestTimeConversion(unittest.TestCase):

    def test_seconds_to_hms_basic(self):
        self.assertEqual(seconds_to_hms(3661), (1, 1, 1))

    def test_seconds_to_hms_zero(self):
        self.assertEqual(seconds_to_hms(0), (0, 0, 0))

    def test_seconds_to_hms_large(self):
        self.assertEqual(seconds_to_hms(86400), (24, 0, 0))

    def test_seconds_to_hms_large_span(self):
        self.assertEqual(seconds_to_hms(1000000), (277, 46, 40))

    def test_seconds_to_hms_negative(self):
        with self.assertRaises(ValueError):
            seconds_to_hms(-1)

    def test_seconds_to_hms_invalid_type(self):
        with self.assertRaises(TypeError):
            seconds_to_hms("abc")

    def test_hms_to_seconds_basic(self):
        self.assertEqual(hms_to_seconds(1, 1, 1), 3661)

    def test_hms_to_seconds_zero(self):
        self.assertEqual(hms_to_seconds(0, 0, 0), 0)

    def test_hms_to_seconds_large(self):
        self.assertEqual(hms_to_seconds(24, 0, 0), 86400)

    def test_hms_to_seconds_large_span(self):
        self.assertEqual(hms_to_seconds(277, 46, 40), 1000000)

    def test_hms_to_seconds_negative(self):
        with self.assertRaises(ValueError):
            hms_to_seconds(-1, 0, 0)

    def test_hms_to_seconds_invalid_type(self):
        with self.assertRaises(TypeError):
            hms_to_seconds("a", 0, 0)

if __name__ == '__main__':
    print(seconds_to_hms(3661))
    print(seconds_to_hms(0))
    print(seconds_to_hms(86400))
    print(hms_to_seconds(1, 1, 1))
    print(hms_to_seconds(0, 0, 0))
    print(hms_to_seconds(24, 0, 0))
    unittest.main()

import pytz
from datetime import datetime

def convert_timezone(dt, target_tz_name):
    if dt is None:
        raise ValueError("datetime object cannot be None")
    if target_tz_name is None:
        raise ValueError("Time zone name cannot be None")

    if dt.tzinfo is not None:
        dt_utc = dt.astimezone(pytz.utc)
    else:
        dt_utc = pytz.utc.localize(dt)

    target_tz = pytz.timezone(target_tz_name)
    converted_dt = dt_utc.astimezone(target_tz)
    return converted_dt

if __name__ == '__main__':
    sample_dt = datetime(2023, 10, 25, 12, 0, 0)
    sample_tz = "America/New_York"
    result = convert_timezone(sample_dt, sample_tz)
    print(result)

import unittest

def seconds_to_hms(total_seconds):
    if total_seconds < 0:
        raise ValueError("Total seconds must be non-negative")
    hours = int(total_seconds) // 3600
    remainder = int(total_seconds) % 3600
    minutes = remainder // 60
    seconds = remainder % 60
    return (hours, minutes, seconds)

def hms_to_seconds(hours, minutes, seconds):
    if hours < 0 or minutes < 0 or seconds < 0:
        raise ValueError("Time components must be non-negative")
    if minutes >= 60 or seconds >= 60:
        raise ValueError("Minutes and seconds must be less than 60")
    return hours * 3600 + minutes * 60 + seconds

def format_hms(hours, minutes, seconds):
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"

def parse_hms(time_str):
    parts = time_str.split(':')
    if len(parts) != 3:
        raise ValueError("Time string must be in HH:MM:SS format")
    hours = int(parts[0])
    minutes = int(parts[1])
    seconds = int(parts[2])
    return (hours, minutes, seconds)

class TestTimeConversions(unittest.TestCase):
    def test_seconds_to_hms_zero(self):
        result = seconds_to_hms(0)
        self.assertEqual(result, (0, 0, 0))

    def test_seconds_to_hms_exact_hours(self):
        result = seconds_to_hms(3600)
        self.assertEqual(result, (1, 0, 0))

    def test_seconds_to_hms_exact_minutes(self):
        result = seconds_to_hms(60)
        self.assertEqual(result, (0, 1, 0))

    def test_seconds_to_hms_exact_seconds(self):
        result = seconds_to_hms(45)
        self.assertEqual(result, (0, 0, 45))

    def test_seconds_to_hms_combined(self):
        result = seconds_to_hms(3661)
        self.assertEqual(result, (1, 1, 1))

    def test_seconds_to_hms_large_value(self):
        result = seconds_to_hms(86400)
        self.assertEqual(result, (24, 0, 0))

    def test_seconds_to_hms_negative(self):
        with self.assertRaises(ValueError):
            seconds_to_hms(-1)

    def test_seconds_to_hms_fractional(self):
        result = seconds_to_hms(3661.9)
        self.assertEqual(result, (1, 1, 1))

    def test_hms_to_seconds_zero(self):
        result = hms_to_seconds(0, 0, 0)
        self.assertEqual(result, 0)

    def test_hms_to_seconds_hours(self):
        result = hms_to_seconds(1, 0, 0)
        self.assertEqual(result, 3600)

    def test_hms_to_seconds_combined(self):
        result = hms_to_seconds(1, 1, 1)
        self.assertEqual(result, 3661)

    def test_hms_to_seconds_negative_hours(self):
        with self.assertRaises(ValueError):
            hms_to_seconds(-1, 0, 0)

    def test_hms_to_seconds_negative_minutes(self):
        with self.assertRaises(ValueError):
            hms_to_seconds(0, -1, 0)

    def test_hms_to_seconds_invalid_minutes(self):
        with self.assertRaises(ValueError):
            hms_to_seconds(0, 60, 0)

    def test_hms_to_seconds_invalid_seconds(self):
        with self.assertRaises(ValueError):
            hms_to_seconds(0, 0, 60)

    def test_format_hms_simple(self):
        result = format_hms(1, 2, 3)
        self.assertEqual(result, "01:02:03")

    def test_format_hms_single_digits(self):
        result = format_hms(0, 0, 0)
        self.assertEqual(result, "00:00:00")

    def test_format_hms_large_values(self):
        result = format_hms(99, 59, 59)
        self.assertEqual(result, "99:59:59")

    def test_parse_hms_valid(self):
        result = parse_hms("01:02:03")
        self.assertEqual(result, (1, 2, 3))

    def test_parse_hms_invalid_format(self):
        with self.assertRaises(ValueError):
            parse_hms("1:2")

    def test_parse_hms_with_leading_zeros(self):
        result = parse_hms("00:00:00")
        self.assertEqual(result, (0, 0, 0))

    def test_round_trip_conversion(self):
        original_seconds = 12345
        hms = seconds_to_hms(original_seconds)
        converted_seconds = hms_to_seconds(*hms)
        self.assertEqual(converted_seconds, original_seconds)

    def test_round_trip_large_span(self):
        original_seconds = 1000000
        hms = seconds_to_hms(original_seconds)
        converted_seconds = hms_to_seconds(*hms)
        self.assertEqual(converted_seconds, original_seconds)

if __name__ == '__main__':
    test = unittest.TestLoader().loadTestsFromTestCase(TestTimeConversions)
    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(test)
    print(result)

