import math
from typing import List, Union, Optional

class Shape:
    def area(self) -> float:
        raise ValueError("Base class should not be used directly")

    def scale(self, factor: float) -> None:
        if factor <= 0:
            raise ValueError("Scale factor must be positive")

class Circle(Shape):
    def __init__(self, radius: float) -> None:
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2

    def scale(self, factor: float) -> None:
        super().scale(factor)
        self.radius *= factor

class Rectangle(Shape):
    def __init__(self, width: float, height: float) -> None:
        self.width = width
        self.height = height

    def area(self) -> float:
        return self.width * self.height

    def scale(self, factor: float) -> None:
        super().scale(factor)
        self.width *= factor
        self.height *= factor

class Triangle(Shape):
    def __init__(self, base: float, height: float) -> None:
        self.base = base
        self.height = height

    def area(self) -> float:
        return 0.5 * self.base * self.height

    def scale(self, factor: float) -> None:
        super().scale(factor)
        self.base *= factor
        self.height *= factor

def calculate_scaled_area(shape: Shape, factor: float) -> float:
    scaled_shape = shape.__class__(*shape.__dict__.values())
    scaled_shape.scale(factor)
    return scaled_shape.area()

if __name__ == '__main__':
    circle = Circle(5.0)
    print(calculate_scaled_area(circle, 2.0))

    rectangle = Rectangle(4.0, 6.0)
    print(calculate_scaled_area(rectangle, 1.5))

    triangle = Triangle(10.0, 8.0)
    print(calculate_scaled_area(triangle, 0.5))

def calculate_polygon_area(vertices):
    n = len(vertices)
    if n < 3:
        return 0.0

    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        area += vertices[i][0] * vertices[j][1]
        area -= vertices[j][0] * vertices[i][1]

    area = abs(area) / 2.0

    if isinstance(area, float):
        if area == 0.0:
            return 0.0
        if abs(area) < 1e-10:
            return 0.0

    return round(area, 10)

if __name__ == '__main__':
    sample_polygon = [(0, 0), (4, 0), (4, 3), (0, 3)]
    result = calculate_polygon_area(sample_polygon)
    print(result)

import math

class GeometricShape:
    def __init__(self, name: str, area: float) -> None:
        self.name = name
        self.area = area

    def calculate_area(self) -> float:
        return self.area

    def scale_area(self, factor: float) -> float:
        self.area = self.area * factor
        return self.area

class Circle(GeometricShape):
    def __init__(self, radius: float) -> None:
        if radius < 0:
            raise ValueError("Radius cannot be negative")
        self.radius = radius
        super().__init__("Circle", math.pi * (radius ** 2))

class Rectangle(GeometricShape):
    def __init__(self, width: float, height: float) -> None:
        if width < 0 or height < 0:
            raise ValueError("Dimensions cannot be negative")
        self.width = width
        self.height = height
        super().__init__("Rectangle", width * height)

