    @staticmethod
    def cubic_meters_to_cubic_inches(cubic_meters):
        return cubic_meters * VolumeConverter.CUBIC_METERS_TO_CUBIC_INCHES

    @staticmethod
    def cubic_inches_to_cubic_meters(cubic_inches):
