    sample_filename = 'volumes.json'
    sample_data = [1000, 5000, 25000, 100000]
    with open(sample_filename, 'w') as f:
        json.dump(sample_data, f)
    converted_values = process_volume_data(sample_filename)
    for original, liters, cubic_meters in converted_values:
        print(f'{original} ml -> {liters} liters -> {cubic_meters} m³')
    os.remove(sample_filename)

import os
import tempfile

def convert_volumes(measurements, unit="liters"):
    results = []
    for measurement in measurements:
        if unit.lower() == "liters":
            cubic_meters = measurement / 1000.0
            liters = measurement
        elif unit.lower() == "cubic_meters":
            cubic_meters = measurement
            liters = measurement * 1000.0
        else:
            raise ValueError("Unsupported unit")
        results.append((liters, cubic_meters))
    return results

def process_volume_file(filepath):
    try:
        with open(filepath, 'r') as file:
            lines = file.readlines()
    except FileNotFoundError:
        return []
    except IOError:
        return []

    measurements = []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            value = float(stripped)
            measurements.append(value)
        except ValueError:
            continue

    return convert_volumes(measurements, "liters")

