        "1.5",
        "100",
        "0.001",
        "-50",
        "abc",
        "123.456",
        "",
        "999.999"
    ]

    with tempfile.NamedTemporaryFile(mode='w', suffix='.txt', delete=False) as f:
        temp_file_path = f.name
        f.write('\n'.join(sample_data))

    try:
        results = convert_volume_measurements(temp_file_path)
        print_volume_conversions(results)
    finally:
        if os.path.exists(temp_file_path):
            os.remove(temp_file_path)

if __name__ == '__main__':
    main()

def process_volume_file(file_path):
    liters_to_cubic_meters = 0.001
    results = []
    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        return ["Error: File not found"]
    except IOError:
        return ["Error: Could not read file"]

    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if not parts:
            continue
        value_str = parts[0]
        try:
            value = float(value_str)
        except ValueError:
            results.append(f"Error: Invalid number '{value_str}'")
            continue
        liters = value
        cubic_meters = liters * liters_to_cubic_meters
        results.append((liters, cubic_meters))
    return results

