        context = {"value": value}
        super().__init__(f"Zero value is not allowed: {value}", context)

CONVERSION_FACTORS = {
    "meters": 1.0,
    "feet": 0.3048,
    "inches": 0.0254,
    "yards": 0.9144,
    "kilometers": 1000.0,
    "centimeters": 0.01,
}

def convert_length(value, from_unit, to_unit):
    if not isinstance(value, (int, float)):
        raise InvalidValueError(value)
    if value < 0:
