from typing import Dict, Union

L_PER_GAL: float = 0.00378541
ML_PER_L: float = 1000.0
M3_PER_L: float = 0.001

CONVERSION_FACTORS: Dict[str, float] = {
    "mL": ML_PER_L,
    "L": 1.0,
    "gal": 1.0 / L_PER_GAL,
    "m³": 1.0 / M3_PER_L
}

TARGET_UNITS: Dict[str, str] = {
    "mL": "mL",
    "L": "L",
    "gal": "L",
    "m³": "L"
}

UNIT_TO_LITER: Dict[str, float] = {
    "mL": ML_PER_L,
    "L": 1.0,
    "gal": 1.0 / L_PER_GAL,
    "m³": 1.0 / M3_PER_L
}

UNIT_FROM_LITER: Dict[str, float] = {
    "mL": 1.0 / ML_PER_L,
    "L": 1.0,
    "gal": L_PER_GAL,
    "m³": M3_PER_L
}

def convert_volume(value: float, unit_from: str, unit_to: str) -> float:
    if unit_from not in UNIT_TO_LITER:
        raise ValueError(f"Unsupported source unit: {unit_from}")
    if unit_to not in UNIT_FROM_LITER:
        raise ValueError(f"Unsupported target unit: {unit_to}")

    liters = value * UNIT_TO_LITER[unit_from]
    result = liters * UNIT_FROM_LITER[unit_to]
    return result

def list_supported_units() -> list:
    return list(UNIT_TO_LITER.keys())

if __name__ == '__main__':
    val: float = 1.0
    src_unit: str = "gal"
    tgt_unit: str = "L"

    converted: float = convert_volume(val, src_unit, tgt_unit)
    print(converted)

class ConversionError(Exception):
    def __init__(self, message, metadata):
        super().__init__(message)
        self.metadata = metadata

class UnknownUnitError(ConversionError):
    def __init__(self, unit_name):
        supported = ["km", "m", "ft", "in"]
        message = f"Unknown unit '{unit_name}'. Supported units: {supported}"
        super().__init__(message, {"unit": unit_name, "supported": supported})

class NegativeValueError(ConversionError):
    def __init__(self, value):
        message = f"Value cannot be negative: {value}"
        super().__init__(message, {"value": value})

class ZeroValueError(ConversionError):
    def __init__(self, value):
        message = f"Value cannot be zero: {value}"
        super().__init__(message, {"value": value})

UNIT_FACTORS_TO_METERS = {
    "km": 1000.0,
    "m": 1.0,
    "ft": 0.3048,
    "in": 0.0254
}

def convert_unit(value, from_unit, to_unit):
    if from_unit not in UNIT_FACTORS_TO_METERS:
        raise UnknownUnitError(from_unit)
    if to_unit not in UNIT_FACTORS_TO_METERS:
        raise UnknownUnitError(to_unit)

    if value < 0:
        raise NegativeValueError(value)

    if value == 0:
        raise ZeroValueError(value)

    meters = value * UNIT_FACTORS_TO_METERS[from_unit]
    result = meters / UNIT_FACTORS_TO_METERS[to_unit]
    return result

if __name__ == '__main__':
    try:
        result1 = convert_unit(1000, "m", "km")
        print(result1)

        result2 = convert_unit(5, "km", "m")
        print(result2)

        result3 = convert_unit(6, "ft", "m")
        print(result3)

        result4 = convert_unit(12, "in", "ft")
        print(result4)

        try:
            convert_unit(10, "m", "invalid")
        except UnknownUnitError as e:
            print(str(e))

        try:
            convert_unit(-5, "m", "km")
        except NegativeValueError as e:
            print(str(e))

        try:
            convert_unit(0, "m", "km")
        except ZeroValueError as e:
            print(str(e))

    except Exception as e:
        print(str(e))

import argparse
import sys

class VolumeConverter:
    VALID_UNITS = {'liters', 'milliliters', 'gallons', 'quarts', 'pints', 'cups'}

    def __init__(self, value, from_unit, to_unit):
        self.value = value
        self.from_unit = from_unit
        self.to_unit = to_unit
        self._validate_units()

    def _validate_units(self):
        if self.from_unit.lower() not in self.VALID_UNITS:
            raise ValueError(f"Invalid input unit: {self.from_unit}. Must be one of {self.VALID_UNITS}")
        if self.to_unit.lower() not in self.VALID_UNITS:
            raise ValueError(f"Invalid output unit: {self.to_unit}. Must be one of {self.VALID_UNITS}")
        if not isinstance(self.value, (int, float)):
            raise TypeError("Value must be a number")
        if self.value < 0:
            raise ValueError("Volume cannot be negative")

    def _to_liters(self, value, unit):
        unit = unit.lower()
        if unit == 'liters':
            return value
        elif unit == 'milliliters':
            return value / 1000
        elif unit == 'gallons':
            return value * 3.78541
        elif unit == 'quarts':
            return value * 0.946353
        elif unit == 'pints':
            return value * 0.473176
        elif unit == 'cups':
            return value * 0.236588
        else:
            raise ValueError(f"Unsupported unit: {unit}")

    def _from_liters(self, value, unit):
        unit = unit.lower()
        if unit == 'liters':
            return value
        elif unit == 'milliliters':
            return value * 1000
        elif unit == 'gallons':
            return value / 3.78541
        elif unit == 'quarts':
            return value / 0.946353
        elif unit == 'pints':
            return value / 0.473176
        elif unit == 'cups':
            return value / 0.236588
        else:
            raise ValueError(f"Unsupported unit: {unit}")

    def convert(self):
        liters = self._to_liters(self.value, self.from_unit)
        result = self._from_liters(liters, self.to_unit)
        return result

def main():
    parser = argparse.ArgumentParser(description='Convert volume units')
    parser.add_argument('volume', type=float, help='The volume value to convert')
    parser.add_argument('from_unit', type=str, help='The unit of the input volume')
    parser.add_argument('to_unit', type=str, help='The desired output unit')

    args = parser.parse_args()

    try:
        converter = VolumeConverter(args.volume, args.from_unit, args.to_unit)
        result = converter.convert()
        print(f"{args.volume} {args.from_unit} is equal to {result} {args.to_unit}")
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)
    except TypeError as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == '__main__':
    sample_volume = 5.0
    sample_from_unit = 'gallons'
    sample_to_unit = 'liters'

    converter = VolumeConverter(sample_volume, sample_from_unit, sample_to_unit)
    output = converter.convert()
    print(f"{sample_volume} {sample_from_unit} is equal to {output} {sample_to_unit}")

class InvalidConversionUnitError(Exception):
    def __init__(self, unit):
        message = f"Unsupported conversion unit: {unit}"
        super().__init__(message)
        self.unit = unit

class NegativeValueError(Exception):
    def __init__(self, value):
        message = f"Value cannot be negative: {value}"
        super().__init__(message)
        self.value = value

class ConversionFactorError(Exception):
    def __init__(self, from_unit, to_unit):
        message = f"No conversion factor defined from {from_unit} to {to_unit}"
        super().__init__(message)
        self.from_unit = from_unit
        self.to_unit = to_unit

CONVERSION_FACTORS = {
    ("km", "m"): 1000,
    ("m", "km"): 0.001,
    ("ft", "m"): 0.3048,
    ("m", "ft"): 3.28084,
    ("lb", "kg"): 0.453592,
    ("kg", "lb"): 2.20462,
    ("celsius", "fahrenheit"): lambda x: (x * 9/5) + 32,
    ("fahrenheit", "celsius"): lambda x: (x - 32) * 5/9,
}

def convert(value, from_unit, to_unit):
    if value < 0 and from_unit not in ("celsius", "fahrenheit"):
        raise NegativeValueError(value)

    if from_unit == to_unit:
        return value

    key = (from_unit, to_unit)

    if key not in CONVERSION_FACTORS:
        raise ConversionFactorError(from_unit, to_unit)

    factor_or_func = CONVERSION_FACTORS[key]

    if callable(factor_or_func):
        result = factor_or_func(value)
    else:
        result = value * factor_or_func

    return result

if __name__ == '__main__':
    sample_results = []

    try:
        result1 = convert(5, "km", "m")
        sample_results.append(("km_to_m", result1))
    except Exception as e:
        sample_results.append(("km_to_m", str(e)))

    try:
        result2 = convert(100, "m", "km")
        sample_results.append(("m_to_km", result2))
    except Exception as e:
        sample_results.append(("m_to_km", str(e)))

    try:
        result3 = convert(-10, "km", "m")
        sample_results.append(("negative_km", result3))
    except NegativeValueError as e:
        sample_results.append(("negative_km", f"NegativeValueError: {e.value}"))
    except Exception as e:
        sample_results.append(("negative_km", str(e)))

    try:
        result4 = convert(20, "celsius", "fahrenheit")
        sample_results.append(("celsius_to_fahrenheit", result4))
    except Exception as e:
        sample_results.append(("celsius_to_fahrenheit", str(e)))

    try:
        result5 = convert(100, "invalid_unit", "m")
        sample_results.append(("invalid_unit", result5))
    except ConversionFactorError as e:
        sample_results.append(("invalid_unit", f"ConversionFactorError: {e.from_unit} -> {e.to_unit}"))
    except Exception as e:
        sample_results.append(("invalid_unit", str(e)))

    for test_name, result in sample_results:
        print(f"{test_name}: {result}")

from __future__ import annotations

from typing import Union

MetricUnit = Union[float, int]
ImperialUnit = Union[float, int]

def convert_metric_to_imperial(
    value: float,
    unit: str
) -> float:
    if unit == 'L':
        return value * 0.264172
    if unit == 'mL':
        return (value / 1000.0) * 0.264172
    if unit == 'm³':
        return value * 264.172
    raise ValueError(f"Unsupported metric unit: {unit}")

def convert_imperial_to_metric(
    value: float,
    unit: str
) -> float:
    if unit == 'L':
        return value / 0.264172
    if unit == 'gal':
        return value / 0.264172
    raise ValueError(f"Unsupported imperial unit: {unit}")

def convert_volume(
    value: float,
    from_unit: str,
    to_unit: str
) -> float:
    if from_unit == to_unit:
        return value

    metric_units = {'L', 'mL', 'm³'}
    imperial_units = {'gal'}

    if from_unit not in metric_units and from_unit not in imperial_units:
        raise ValueError(f"Unknown source unit: {from_unit}")
    if to_unit not in metric_units and to_unit not in imperial_units:
        raise ValueError(f"Unknown target unit: {to_unit}")

    if from_unit in metric_units and to_unit in imperial_units:
        intermediate = convert_metric_to_imperial(value, from_unit)
        return intermediate
    if from_unit in imperial_units and to_unit in metric_units:
        intermediate = convert_imperial_to_metric(value, from_unit)
        return intermediate

    return value

if __name__ == '__main__':
    liters = 5.0
    gallons = convert_volume(liters, 'L', 'gal')
    print(gallons)

    gallons_input = 2.5
    liters_out = convert_volume(gallons_input, 'gal', 'L')
    print(liters_out)

    milliliters = 1000.0
    cubic_meters = convert_volume(milliliters, 'mL', 'm³')
    print(cubic_meters)

