import argparse
import sys

class VolumeConverter:
    VALID_UNITS = {"liter", "milliliter", "gallon_us", "gallon_uk", "quart_us", "pint_us", "cup_us", "fluid_ounce_us"}

    def __init__(self):
        self.factor_to_liter = {
            "liter": 1.0,
            "milliliter": 0.001,
            "gallon_us": 3.785411784,
            "gallon_uk": 4.54609,
            "quart_us": 0.946352946,
            "pint_us": 0.473176473,
            "cup_us": 0.2365882365,
            "fluid_ounce_us": 0.0295735295625
        }

    def convert(self, value, input_unit, output_unit):
        if input_unit not in self.VALID_UNITS:
            raise ValueError(f"Invalid input unit: {input_unit}. Supported units: {', '.join(sorted(self.VALID_UNITS))}")
        if output_unit not in self.VALID_UNITS:
            raise ValueError(f"Invalid output unit: {output_unit}. Supported units: {', '.join(sorted(self.VALID_UNITS))}")

        if value < 0:
            raise ValueError("Volume cannot be negative.")

        liters = value * self.factor_to_liter[input_unit]
        result = liters / self.factor_to_liter[output_unit]
        return result

def parse_arguments(args):
    parser = argparse.ArgumentParser(description="Convert volume between different units.")
    parser.add_argument("volume", type=float, help="The volume value to convert.")
    parser.add_argument("input_unit", type=str, help="The unit of the input volume.")
    parser.add_argument("output_unit", type=str, help="The desired output unit.")
    return parser.parse_args(args)

def main():
    sample_args = ["10", "gallon_us", "liter"]
    try:
        parsed_args = parse_arguments(sample_args)
        converter = VolumeConverter()
        result = converter.convert(parsed_args.volume, parsed_args.input_unit, parsed_args.output_unit)
        print(f"{parsed_args.volume} {parsed_args.input_unit} is equal to {result} {parsed_args.output_unit}")
    except ValueError as e:
        print(f"Error: {e}")
    except SystemExit as e:
        sys.exit(e.code)

if __name__ == '__main__':
    main()

class TemperatureConversionError(Exception):
    def __init__(self, message, context):
        super().__init__(message)
        self.context = context

class InvalidUnitError(TemperatureConversionError):
    def __init__(self, unit, valid_units):
        message = f"Unit '{unit}' is not valid. Valid units are: {valid_units}"
        super().__init__(message, {"invalid_unit": unit, "valid_units": valid_units})

class OutOfRangeError(TemperatureConversionError):
    def __init__(self, value, unit, minimum):
        message = f"Value {value} in {unit} is below absolute zero ({minimum})."
        super().__init__(message, {"value": value, "unit": unit, "minimum": minimum})

class ConversionLogicError(TemperatureConversionError):
    def __init__(self, details):
        message = "Conversion logic failed due to unsupported unit combination or internal error."
        super().__init__(message, details)

VALID_UNITS = ["C", "F", "K"]

def to_celsius(value, from_unit):
    if from_unit == "C":
        return value
    if from_unit == "F":
        return (value - 32) * 5 / 9
    if from_unit == "K":
        return value - 273.15
    raise ConversionLogicError({"reason": "Unexpected unit reached in to_celsius", "unit": from_unit})

def from_celsius(value, to_unit):
    if to_unit == "C":
        return value
    if to_unit == "F":
        return value * 9 / 5 + 32
    if to_unit == "K":
        return value + 273.15
    raise ConversionLogicError({"reason": "Unexpected unit reached in from_celsius", "unit": to_unit})

def validate_physical_constraints(value, unit):
    if unit == "K" and value < 0:
        raise OutOfRangeError(value, "K", 0)
    if unit == "C" and value < -273.15:
        raise OutOfRangeError(value, "C", -273.15)
    if unit == "F" and value < -459.67:
        raise OutOfRangeError(value, "F", -459.67)

def convert_temperature(value, from_unit, to_unit):
    if from_unit not in VALID_UNITS:
        raise InvalidUnitError(from_unit, VALID_UNITS)
    if to_unit not in VALID_UNITS:
        raise InvalidUnitError(to_unit, VALID_UNITS)

    validate_physical_constraints(value, from_unit)

    celsius_value = to_celsius(value, from_unit)
    result = from_celsius(celsius_value, to_unit)

    validate_physical_constraints(result, to_unit)

    return round(result, 2)

if __name__ == '__main__':
    print(convert_temperature(100, "C", "F"))
    print(convert_temperature(32, "F", "C"))
    print(convert_temperature(0, "C", "K"))

    try:
        convert_temperature(100, "X", "C")
    except InvalidUnitError as e:
        print(e)

    try:
        convert_temperature(-500, "K", "C")
    except OutOfRangeError as e:
        print(e)

    try:
        convert_temperature(300, "C", "Y")
    except InvalidUnitError as e:
        print(e)

from dataclasses import dataclass
from typing import Union

VOLUME_CONVERSIONS = {
    "ml_to_l": 0.001,
    "l_to_ml": 1000.0,
    "m3_to_l": 1000.0,
    "l_to_m3": 0.001,
    "gal_to_l": 3.78541,
    "l_to_gal": 0.264172,
}

def convert_volume(value: float, from_unit: str, to_unit: str) -> float:
    if from_unit == to_unit:
        return value

    from_unit = from_unit.lower()
    to_unit = to_unit.lower()

    if from_unit == "ml" and to_unit == "l":
        return value * VOLUME_CONVERSIONS["ml_to_l"]
    elif from_unit == "l" and to_unit == "ml":
        return value * VOLUME_CONVERSIONS["l_to_ml"]
    elif from_unit == "m3" and to_unit == "l":
        return value * VOLUME_CONVERSIONS["m3_to_l"]
    elif from_unit == "l" and to_unit == "m3":
        return value * VOLUME_CONVERSIONS["l_to_m3"]
    elif from_unit == "gal" and to_unit == "l":
        return value * VOLUME_CONVERSIONS["gal_to_l"]
    elif from_unit == "l" and to_unit == "gal":
        return value * VOLUME_CONVERSIONS["l_to_gal"]
    elif from_unit == "ml" and to_unit == "m3":
        return value * VOLUME_CONVERSIONS["ml_to_l"] * VOLUME_CONVERSIONS["l_to_m3"]
    elif from_unit == "m3" and to_unit == "ml":
        return value * VOLUME_CONVERSIONS["m3_to_l"] * VOLUME_CONVERSIONS["l_to_ml"]
    elif from_unit == "ml" and to_unit == "gal":
        return value * VOLUME_CONVERSIONS["ml_to_l"] * VOLUME_CONVERSIONS["l_to_gal"]
    elif from_unit == "gal" and to_unit == "ml":
        return value * VOLUME_CONVERSIONS["gal_to_l"] * VOLUME_CONVERSIONS["l_to_ml"]
    elif from_unit == "m3" and to_unit == "gal":
        return value * VOLUME_CONVERSIONS["m3_to_l"] * VOLUME_CONVERSIONS["l_to_gal"]
    elif from_unit == "gal" and to_unit == "m3":
        return value * VOLUME_CONVERSIONS["gal_to_l"] * VOLUME_CONVERSIONS["l_to_m3"]
    else:
        raise ValueError(f"Unsupported conversion from {from_unit} to {to_unit}")

