from typing import Union
from dataclasses import dataclass

@dataclass(frozen=True)
class Volume:
    liters: float

    def to_milliliters(self) -> float:
        return self.liters * 1000

    def to_cubic_meters(self) -> float:
        return self.liters / 1000

    def to_gallons(self) -> float:
        return self.liters / 3.785411784

def convert_to_liters(value: Union[float, int], unit: str) -> float:
    unit_lower = unit.lower()
    if unit_lower == 'l' or unit_lower == 'liter' or unit_lower == 'liters':
        return float(value)
    elif unit_lower == 'ml' or unit_lower == 'milliliter' or unit_lower == 'milliliters':
        return float(value) / 1000
    elif unit_lower == 'm3' or unit_lower == 'm3' or unit_lower == 'cubic meter' or unit_lower == 'cubic meters':
        return float(value) * 1000
    elif unit_lower == 'gal' or unit_lower == 'gallon' or unit_lower == 'gallons':
        return float(value) * 3.785411784
    else:
        raise ValueError(f"Unsupported unit: {unit}")

def convert_volume(value: Union[float, int], from_unit: str, to_unit: str) -> float:
    liters = convert_to_liters(value, from_unit)
    target_volume = Volume(liters=liters)

    to_lower = to_unit.lower()
    if to_lower == 'l' or to_lower == 'liter' or to_lower == 'liters':
        return liters
    elif to_lower == 'ml' or to_lower == 'milliliter' or to_lower == 'milliliters':
        return target_volume.to_milliliters()
    elif to_lower == 'm3' or to_lower == 'm3' or to_lower == 'cubic meter' or to_lower == 'cubic meters':
        return target_volume.to_cubic_meters()
    elif to_lower == 'gal' or to_lower == 'gallon' or to_lower == 'gallons':
        return target_volume.to_gallons()
    else:
        raise ValueError(f"Unsupported target unit: {to_unit}")

if __name__ == '__main__':
    sample_volume_val = 2.5
    sample_from_unit = 'gal'
    sample_to_unit = 'l'
    result_1 = convert_volume(sample_volume_val, sample_from_unit, sample_to_unit)
    print(result_1)

    sample_to_unit_2 = 'ml'
    result_2 = convert_volume(sample_volume_val, sample_from_unit, sample_to_unit_2)
    print(result_2)

    sample_to_unit_3 = 'm3'
    result_3 = convert_volume(sample_volume_val, sample_from_unit, sample_to_unit_3)
    print(result_3)

    vol_instance = Volume(liters=100.0)
    print(vol_instance.to_milliliters())
    print(vol_instance.to_cubic_meters())
    print(vol_instance.to_gallons())

class ConversionError(Exception):
    def __init__(self, message, metadata):
        super().__init__(message)
        self.metadata = metadata

class UnsupportedUnitError(ConversionError):
    def __init__(self, unit, supported_units):
        message = f"Unit {unit} is not supported. Valid units are {supported_units}"
        super().__init__(message, {"unit": unit, "supported": supported_units})

class InvalidValueError(ConversionError):
    def __init__(self, value):
        message = f"Value must be a positive number, got {value}"
        super().__init__(message, {"value": value})

class ZeroDivisionError(ConversionError):
    def __init__(self):
        message = "Cannot divide by zero"
        super().__init__(message, {})

UNIT_CONVERSIONS = {
    "celsius": {"fahrenheit": lambda x: x * 9/5 + 32, "kelvin": lambda x: x + 273.15},
    "fahrenheit": {"celsius": lambda x: (x - 32) * 5/9, "kelvin": lambda x: (x - 32) * 5/9 + 273.15},
    "kelvin": {"celsius": lambda x: x - 273.15, "fahrenheit": lambda x: (x - 273.15) * 9/5 + 32}
}

def convert_temperature(value, from_unit, to_unit):
    if not isinstance(value, (int, float)):
        raise InvalidValueError(value)
    if value < 0 and from_unit.lower() == "kelvin":
        raise InvalidValueError(value)
    from_lower = from_unit.lower()
    to_lower = to_unit.lower()
    if from_lower not in UNIT_CONVERSIONS:
        raise UnsupportedUnitError(from_unit, list(UNIT_CONVERSIONS.keys()))
    if to_lower not in UNIT_CONVERSIONS[from_lower]:
        raise UnsupportedUnitError(to_unit, list(UNIT_CONVERSIONS[from_lower].keys()))
    if from_lower == to_lower:
        return value
    conversion_function = UNIT_CONVERSIONS[from_lower][to_lower]
    return conversion_function(value)

if __name__ == '__main__':
    result1 = convert_temperature(100, "celsius", "fahrenheit")
    print(result1)
    result2 = convert_temperature(32, "fahrenheit", "celsius")
    print(result2)
    result3 = convert_temperature(0, "celsius", "kelvin")
    print(result3)
    try:
        convert_temperature(-10, "kelvin", "celsius")
    except ConversionError as e:
        print(str(e))
    try:
        convert_temperature(100, "celsius", "rankine")
    except ConversionError as e:
        print(str(e))
    try:
        convert_temperature("hot", "celsius", "fahrenheit")
    except ConversionError as e:
        print(str(e))

from enum import Enum
from typing import Union

class VolumeUnit(Enum):
    MILLILITER = "mL"
    LITER = "L"
    CUBIC_METER = "m3"
    GALLON = "gal"

    def to_liter(self, value: float) -> float:
        if self == VolumeUnit.MILLILITER:
            return value / 1000.0
        if self == VolumeUnit.LITER:
            return value
        if self == VolumeUnit.CUBIC_METER:
            return value * 1000.0
        if self == VolumeUnit.GALLON:
            return value * 3.785411784
        raise ValueError(f"Unsupported unit: {self}")

    def from_liter(self, value: float) -> float:
        if self == VolumeUnit.MILLILITER:
            return value * 1000.0
        if self == VolumeUnit.LITER:
            return value
        if self == VolumeUnit.CUBIC_METER:
            return value / 1000.0
        if self == VolumeUnit.GALLON:
            return value / 3.785411784
        raise ValueError(f"Unsupported unit: {self}")

def convert_volume(value: float, from_unit: VolumeUnit, to_unit: VolumeUnit) -> float:
    if from_unit == to_unit:
        return value
    liter_value = from_unit.to_liter(value)
    return to_unit.from_liter(liter_value)

class VolumeManager:
    def __init__(self, value: float, unit: VolumeUnit):
        self.value = value
        self.unit = unit

    def convert_to(self, target_unit: VolumeUnit) -> float:
        return convert_volume(self.value, self.unit, target_unit)

    def add(self, other: "VolumeManager") -> "VolumeManager":
        total_liters = self.unit.to_liter(self.value) + other.unit.to_liter(other.value)
        return VolumeManager(total_liters, VolumeUnit.LITER)

    def __repr__(self) -> str:
        return f"{self.value} {self.unit.value}"

if __name__ == "__main__":
    initial_volume = 5.0
    input_unit = VolumeUnit.GALLON
    output_unit = VolumeUnit.LITER
    converted_result = convert_volume(initial_volume, input_unit, output_unit)
    print(converted_result)

    manager = VolumeManager(1.0, VolumeUnit.CUBIC_METER)
    gallons_result = manager.convert_to(VolumeUnit.GALLON)
    print(gallons_result)

    v1 = VolumeManager(2.0, VolumeUnit.LITER)
    v2 = VolumeManager(1000.0, VolumeUnit.MILLILITER)
    sum_manager = v1.add(v2)
    print(sum_manager.convert_to(VolumeUnit.MILLILITER))

class VolumeConverter:
    LITER_TO_ML = 1000.0
    GALLON_TO_LITER = 3.785411784
    QUART_TO_GALLON = 0.25
    PINT_TO_QUART = 0.5
    CUP_TO_PINT = 0.5
    FL_OZ_TO_CUP = 0.125

    def __init__(self):
        self._ml = 0.0

    def _to_ml(self, value, unit):
        if unit == 'ml':
            return value
        if unit == 'L':
            return value * self.LITER_TO_ML
        if unit == 'gal':
            return value * self.GALLON_TO_LITER * self.LITER_TO_ML
        if unit == 'qt':
            return value * self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON
        if unit == 'pt':
            return value * self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART
        if unit == 'cup':
            return value * self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART * self.CUP_TO_PINT
        if unit == 'fl_oz':
            return value * self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART * self.CUP_TO_PINT * self.FL_OZ_TO_CUP
        raise ValueError(f"Unknown unit: {unit}")

    def convert(self, value, from_unit, to_unit):
        ml_value = self._to_ml(value, from_unit)
        if to_unit == 'ml':
            return ml_value
        if to_unit == 'L':
            return ml_value / self.LITER_TO_ML
        if to_unit == 'gal':
            return ml_value / (self.GALLON_TO_LITER * self.LITER_TO_ML)
        if to_unit == 'qt':
            return ml_value / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON)
        if to_unit == 'pt':
            return ml_value / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART)
        if to_unit == 'cup':
            return ml_value / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART * self.CUP_TO_PINT)
        if to_unit == 'fl_oz':
            return ml_value / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART * self.CUP_TO_PINT * self.FL_OZ_TO_CUP)
        raise ValueError(f"Unknown target unit: {to_unit}")

    def set_ml(self, value):
        self._ml = value
        return self

    def get_ml(self):
        return self._ml

    def get_L(self):
        return self._ml / self.LITER_TO_ML

    def get_gal(self):
        return self._ml / (self.GALLON_TO_LITER * self.LITER_TO_ML)

    def get_qt(self):
        return self._ml / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON)

    def get_pt(self):
        return self._ml / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART)

    def get_cup(self):
        return self._ml / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART * self.CUP_TO_PINT)

    def get_fl_oz(self):
        return self._ml / (self.GALLON_TO_LITER * self.LITER_TO_ML * self.QUART_TO_GALLON * self.PINT_TO_QUART * self.CUP_TO_PINT * self.FL_OZ_TO_CUP)

if __name__ == '__main__':
    converter = VolumeConverter()
    print(converter.convert(1, 'L', 'ml'))
    print(converter.convert(1, 'gal', 'L'))
    print(converter.convert(32, 'fl_oz', 'cup'))
    print(converter.set_ml(5000).get_gal())

class ConversionBaseError(Exception):
    def __init__(self, message, context):
        super().__init__(message)
        self.context = context

class UnitNotSupportedError(ConversionBaseError):
    def __init__(self, target_unit, supported_units):
        message = f"Target unit '{target_unit}' is not supported. Supported units: {supported_units}"
        super().__init__(message, {"target_unit": target_unit, "supported_units": supported_units})

class InvalidValueError(ConversionBaseError):
    def __init__(self, value):
        message = f"Conversion value must be a positive number, received: {value}"
        super().__init__(message, {"value": value, "type": type(value).__name__})

class ZeroValueError(ConversionBaseError):
    def __init__(self, value):
        message = f"Conversion value cannot be zero, received: {value}"
        super().__init__(message, {"value": value})

class TemperatureUnitError(ConversionBaseError):
    def __init__(self, unit):
        message = f"Invalid temperature unit format: '{unit}'. Expected 'C', 'F', or 'K'."
        super().__init__(message, {"unit": unit})

CONVERSION_FACTORS = {
    "C": {"F": 9 / 5 + 32, "K": 273.15, "C": 1.0},
    "F": {"C": 5 / 9, "K": 5 / 9 * (9 / 5) + 32, "F": 1.0},
    "K": {"C": 1.0, "F": 9 / 5 * (1.0), "K": 1.0}
}

UNIT_MAP = {
    "C": {"C": 1.0, "F": 1.8, "K": 1.0},
    "F": {"C": 5 / 9, "F": 1.0, "K": 5 / 9},
    "K": {"C": 1.0, "F": 9 / 5, "K": 1.0}
}

def get_scale_factor(from_unit, to_unit):
    if from_unit == to_unit:
        return 1.0
    if from_unit == "C" and to_unit == "F":
        return 1.8
    if from_unit == "F" and to_unit == "C":
        return 5 / 9
    if from_unit == "C" and to_unit == "K":
        return 1.0
    if from_unit == "K" and to_unit == "C":
        return 1.0
    if from_unit == "F" and to_unit == "K":
        return 5 / 9
    if from_unit == "K" and to_unit == "F":
        return 9 / 5
    raise UnitNotSupportedError(to_unit, ["C", "F", "K"])

def validate_unit(unit, valid_units):
    if unit not in valid_units:
        raise UnitNotSupportedError(unit, list(valid_units))

def validate_value(value):
    if not isinstance(value, (int, float)):
        raise InvalidValueError(value)
    if value <= 0:
        if value == 0:
            raise ZeroValueError(value)
        raise InvalidValueError(value)

def convert_temperature(value, from_unit, to_unit):
    valid_units = {"C", "F", "K"}
    validate_unit(from_unit, valid_units)
    validate_unit(to_unit, valid_units)
    validate_value(value)
    if from_unit == "C" and to_unit == "F":
        return value * 1.8 + 32
    if from_unit == "F" and to_unit == "C":
        return (value - 32) * 5 / 9
    if from_unit == "C" and to_unit == "K":
        return value + 273.15
    if from_unit == "K" and to_unit == "C":
        return value - 273.15
    if from_unit == "F" and to_unit == "K":
        return (value - 32) * 5 / 9 + 273.15
    if from_unit == "K" and to_unit == "F":
        return (value - 273.15) * 9 / 5 + 32
    return value

class TemperatureConverter:
    def __init__(self):
        self.history = []

    def convert(self, value, from_unit, to_unit):
        result = convert_temperature(value, from_unit, to_unit)
        self.history.append({"input": value, "from": from_unit, "to": to_unit, "output": result})
        return result

    def get_last_result(self):
        if not self.history:
            return None
        return self.history[-1]["output"]

if __name__ == '__main__':
    converter = TemperatureConverter()
    test_cases = [
        (100, "C", "F"),
        (212, "F", "C"),
        (273.15, "K", "C"),
        (0, "C", "K")
    ]
    for val, src, dest in test_cases:
        try:
            res = converter.convert(val, src, dest)
            print(f"Converted {val} {src} to {res} {dest}")
        except ConversionBaseError as e:
            print(f"Error: {e}")
    print(f"Last computed value: {converter.get_last_result()}")

from typing import Dict, Tuple
from dataclasses import dataclass

LITERS_PER_CUBIC_METER: float = 1000.0
MILLILITERS_PER_LITER: float = 1000.0
LITERS_PER_GALLON: float = 3.785411784

@dataclass
class VolumeResult:
    value: float
    unit: str

def to_liters(value: float, unit: str) -> float:
    if unit == "mL":
        return value / MILLILITERS_PER_LITER
    if unit == "L":
        return value
    if unit == "m³":
        return value * LITERS_PER_CUBIC_METER
    if unit == "gal":
        return value * LITERS_PER_GALLON
    raise ValueError(f"Unsupported unit: {unit}")

def from_liters(value: float, target_unit: str) -> float:
    if target_unit == "mL":
        return value * MILLILITERS_PER_LITER
    if target_unit == "L":
        return value
    if target_unit == "m³":
        return value / LITERS_PER_CUBIC_METER
    if target_unit == "gal":
        return value / LITERS_PER_GALLON
    raise ValueError(f"Unsupported target unit: {target_unit}")

def convert_volume(value: float, source_unit: str, target_unit: str) -> VolumeResult:
    liters = to_liters(value, source_unit)
    result_value = from_liters(liters, target_unit)
    return VolumeResult(value=result_value, unit=target_unit)

def get_supported_units() -> Tuple[str, ...]:
    return ("mL", "L", "m³", "gal")

class VolumeManager:
    def __init__(self) -> None:
        self.units = get_supported_units()

    def calculate_conversion(self, amount: float, from_unit: str, to_unit: str) -> float:
        if from_unit not in self.units:
            raise ValueError(f"Invalid source unit: {from_unit}")
        if to_unit not in self.units:
            raise ValueError(f"Invalid target unit: {to_unit}")

        conversion = convert_volume(amount, from_unit, to_unit)
        return conversion.value

    def display_all_conversions(self, amount: float, from_unit: str) -> Dict[str, float]:
        results = {}
        for target in self.units:
            if target != from_unit:
                results[target] = self.calculate_conversion(amount, from_unit, target)
        return results

if __name__ == "__main__":
    manager = VolumeManager()
    sample_amount = 5.0
    sample_unit = "L"

    single_result = manager.calculate_conversion(sample_amount, sample_unit, "gal")
    print(f"{sample_amount} {sample_unit} equals {single_result} gal")

    all_results = manager.display_all_conversions(1.0, "m³")
    for unit, val in all_results.items():
        print(f"1.0 m³ equals {val} {unit}")

from decimal import Decimal, ROUND_HALF_UP
from enum import Enum
from typing import Union

class VolumeUnit(Enum):
    L = "L"
    mL = "mL"
    m3 = "m3"
    gal = "gal"

def convert_volume(value: Union[int, float, Decimal], from_unit: VolumeUnit, to_unit: VolumeUnit) -> Decimal:
    if not isinstance(value, (int, float, Decimal)):
        raise TypeError("Value must be int, float, or Decimal")

    if from_unit == to_unit:
        return Decimal(str(value))

    factor_to_mL = {
        VolumeUnit.L: Decimal("1000"),
        VolumeUnit.mL: Decimal("1"),
        VolumeUnit.m3: Decimal("1000000"),
        VolumeUnit.gal: Decimal("3785.411784"),
    }

    factor_to_target = {
        VolumeUnit.L: Decimal("0.001"),
        VolumeUnit.mL: Decimal("1"),
        VolumeUnit.m3: Decimal("0.000001"),
        VolumeUnit.gal: Decimal("0.000264172"),
    }

    mL_value = Decimal(str(value)) * factor_to_mL[from_unit]

    result = mL_value * factor_to_target[to_unit]

    return result.quantize(Decimal("0.000000000000000000"), rounding=ROUND_HALF_UP)

if __name__ == '__main__':
    result = convert_volume(1, VolumeUnit.gal, VolumeUnit.L)
    print(result)

class VolumeConverter:
    LITERS_PER_GALLON = 3.785411784
    LITERS_PER_QUART = LITERS_PER_GALLON / 4
    LITERS_PER_PINT = LITERS_PER_QUART / 2
    LITERS_PER_CUP = LITERS_PER_PINT / 2
    LITERS_PER_FL_OZ = LITERS_PER_CUP / 8

    def __init__(self, value, unit):
        unit_lower = unit.lower()
        if unit_lower == 'liter' or unit_lower == 'liters' or unit_lower == 'l':
            self.liters = value
        elif unit_lower == 'milliliter' or unit_lower == 'milliliters' or unit_lower == 'ml':
            self.liters = value / 1000
        elif unit_lower == 'gallon' or unit_lower == 'gallons' or unit_lower == 'gal':
            self.liters = value * VolumeConverter.LITERS_PER_GALLON
        elif unit_lower == 'quart' or unit_lower == 'quarts' or unit_lower == 'qt':
            self.liters = value * VolumeConverter.LITERS_PER_QUART
        elif unit_lower == 'pint' or unit_lower == 'pints' or unit_lower == 'pt':
            self.liters = value * VolumeConverter.LITERS_PER_PINT
        elif unit_lower == 'cup' or unit_lower == 'cups' or unit_lower == 'c':
            self.liters = value * VolumeConverter.LITERS_PER_CUP
        elif unit_lower == 'fluid ounce' or unit_lower == 'fluid ounces' or unit_lower == 'fl oz' or unit_lower == 'floz':
            self.liters = value * VolumeConverter.LITERS_PER_FL_OZ
        else:
            raise ValueError(f"Unsupported unit: {unit}")

    def to_liters(self):
        return self.liters

    def to_milliliters(self):
        return self.liters * 1000

    def to_gallons(self):
        return self.liters / VolumeConverter.LITERS_PER_GALLON

    def to_quarts(self):
        return self.liters / VolumeConverter.LITERS_PER_QUART

    def to_pints(self):
        return self.liters / VolumeConverter.LITERS_PER_PINT

    def to_cups(self):
        return self.liters / VolumeConverter.LITERS_PER_CUP

    def to_fluid_ounces(self):
        return self.liters / VolumeConverter.LITERS_PER_FL_OZ

    def convert(self, target_unit):
        target_lower = target_unit.lower()
        if target_lower == 'liter' or target_lower == 'liters' or target_lower == 'l':
            return self.liters
        elif target_lower == 'milliliter' or target_lower == 'milliliters' or target_lower == 'ml':
            return self.liters * 1000
        elif target_lower == 'gallon' or target_lower == 'gallons' or target_lower == 'gal':
            return self.liters / VolumeConverter.LITERS_PER_GALLON
        elif target_lower == 'quart' or target_lower == 'quarts' or target_lower == 'qt':
            return self.liters / VolumeConverter.LITERS_PER_QUART
        elif target_lower == 'pint' or target_lower == 'pints' or target_lower == 'pt':
            return self.liters / VolumeConverter.LITERS_PER_PINT
        elif target_lower == 'cup' or target_lower == 'cups' or target_lower == 'c':
            return self.liters / VolumeConverter.LITERS_PER_CUP
        elif target_lower == 'fluid ounce' or target_lower == 'fluid ounces' or target_lower == 'fl oz' or target_lower == 'floz':
            return self.liters / VolumeConverter.LITERS_PER_FL_OZ
        else:
            raise ValueError(f"Unsupported unit: {target_unit}")

