class VolumeConverter:
    UNIT_NAMES = ['liters', 'milliliters', 'gallons', 'quarts', 'pints', 'cups', 'fluid_ounces']

    CONVERSION_TO_LITERS = {
        'liters': 1.0,
        'milliliters': 0.001,
        'gallons': 3.785411784,
        'quarts': 0.946352946,
        'pints': 0.473176473,
        'cups': 0.2365882365,
        'fluid_ounces': 0.02957352956
    }

    def __init__(self):
        self._conversion_cache = {}

    def _normalize_unit_name(self, unit):
        unit_lower = unit.lower().strip()
        if unit_lower == 'ml':
            return 'milliliters'
        if unit_lower == 'l':
            return 'liters'
        if unit_lower == 'gal':
            return 'gallons'
        if unit_lower == 'qt':
            return 'quarts'
        if unit_lower == 'pt':
            return 'pints'
        if unit_lower == 'cup':
            return 'cups'
        if unit_lower == 'fl_oz' or unit_lower == 'floz':
            return 'fluid_ounces'
        return unit_lower

    def _validate_unit(self, unit):
        normalized = self._normalize_unit_name(unit)
        if normalized not in self.CONVERSION_TO_LITERS:
            raise ValueError(f"Unsupported unit: {unit}")
        return normalized

    def convert(self, value, from_unit, to_unit):
        from_norm = self._validate_unit(from_unit)
        to_norm = self._validate_unit(to_unit)

        if from_norm == to_norm:
            return value

        value_in_liters = value * self.CONVERSION_TO_LITERS[from_norm]
        result = value_in_liters / self.CONVERSION_TO_LITERS[to_norm]
        return result

    def convert_multiple(self, values_and_units, to_unit):
        to_norm = self._validate_unit(to_unit)
        results = []
        for value, unit in values_and_units:
            result = self.convert(value, unit, to_norm)
            results.append(result)
        return results

    def get_supported_units(self):
        return list(self.UNIT_NAMES)

if __name__ == '__main__':
    converter = VolumeConverter()

    liters_to_ml = converter.convert(1.0, 'liters', 'milliliters')
    print(liters_to_ml)

    gallons_to_liters = converter.convert(1.0, 'gallons', 'liters')
    print(gallons_to_liters)

    pints_to_cups = converter.convert(2.0, 'pints', 'cups')
    print(pints_to_cups)

    fl_oz_to_ml = converter.convert(8.0, 'fluid_ounces', 'milliliters')
    print(fl_oz_to_ml)

    quarts_to_gallons = converter.convert(4.0, 'quarts', 'gallons')
    print(quarts_to_gallons)

    mixed_conversions = converter.convert_multiple(
        [(1.0, 'liters'), (1.0, 'gallons'), (16.0, 'fluid_ounces')],
        'milliliters'
    )
    print(mixed_conversions)

    print(converter.get_supported_units())

class VolumeConverter:
    LITERS_TO_BASE = 1.0
    MILLILITERS_TO_BASE = 0.001
    GALLONS_TO_BASE = 3.785411784
    QUARTS_TO_BASE = 0.946352946
    PINTS_TO_BASE = 0.473176473
    CUPS_TO_BASE = 0.236588237
    FLUID_OUNCES_TO_BASE = 0.0295735296

    def __init__(self, value, unit):
        self.value = value
        self.unit = unit
        self._base_value = value * self._get_conversion_factor(unit)

    def _get_conversion_factor(self, unit):
        factors = {
            'liter': self.LITERS_TO_BASE,
            'milliliter': self.MILLILITERS_TO_BASE,
            'gallon': self.GALLONS_TO_BASE,
            'quart': self.QUARTS_TO_BASE,
            'pint': self.PINTS_TO_BASE,
            'cup': self.CUPS_TO_BASE,
            'fluid_ounce': self.FLUID_OUNCES_TO_BASE
        }
        return factors.get(unit, 0.0)

    def convert(self, target_unit):
        factor = self._get_conversion_factor(target_unit)
        if factor == 0.0:
            raise ValueError(f"Unsupported unit: {target_unit}")
        return self._base_value / factor

    def to_liters(self):
        return self.convert('liter')

    def to_milliliters(self):
        return self.convert('milliliter')

    def to_gallons(self):
        return self.convert('gallon')

    def to_quarts(self):
        return self.convert('quart')

    def to_pints(self):
        return self.convert('pint')

    def to_cups(self):
        return self.convert('cup')

    def to_fluid_ounces(self):
        return self.convert('fluid_ounce')

