    test_data = [1, 2, 3, 4, 5]
    print(fetch_final_element(test_data))

def extract_last_item(lst):
    if not lst:
        return None
    MAX_INDEX_OFFSET = 1
    highest_idx = len(lst) - MAX_INDEX_OFFSET
    return [val for idx, val in enumerate(lst) if idx == highest_idx][0]

