def get_middle_value(sequence):
    if not sequence:
        raise ValueError("Sequence is empty")
    sorted_seq = sorted(sequence)
    n = len(sorted_seq)
    mid_index = n // 2
    if n % 2 == 1:
        return sorted_seq[mid_index]
    else:
        return (sorted_seq[mid_index - 1] + sorted_seq[mid_index]) / 2

