def get_median(sequence):
    if not sequence:
        raise ValueError("Sequence cannot be empty")
    n = len(sequence)
    sorted_seq = sorted(sequence)
    mid = n // 2
    if n % 2 == 1:
        return sorted_seq[mid]
    return (sorted_seq[mid - 1] + sorted_seq[mid]) / 2

