def get_nested_element(matrix, row_idx, col_idx, default=None):
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        return default
    if 0 <= row_idx < len(matrix):
        row = matrix[row_idx]
        if 0 <= col_idx < len(row):
            return row[col_idx]
    return default

