import json

class NestedAccessor:
    def __init__(self, data):
        if isinstance(data, str):
            self.data = json.loads(data)
        else:
            self.data = data

    def get(self, path, default=None):
        keys = path.split('.')
        current = self.data
        for key in keys:
            if isinstance(current, dict):
                if key in current:
                    current = current[key]
                else:
                    return default
            elif isinstance(current, list):
                try:
                    index = int(key)
                    if 0 <= index < len(current):
                        current = current[index]
                    else:
                        return default
                except ValueError:
                    return default
            else:
                return default
        return current

