    store = CompositeKeyStore(create_list)
    result_a = store.get_or_init("category", "subcategory", "item")
    result_b = store.get_or_init("category", "subcategory", "item")
    result_c = store.get_or_init("new_cat", "new_sub", "new_item")
    print(result_a)
    print(result_b)
    print(result_c)

