    if index < 0:
        adjusted_index = length + index
        if adjusted_index < 0:
            raise ValueError(f"Index {index} is out of bounds for list of length {length}")
        index = adjusted_index

    if index >= length:
        raise ValueError(f"Index {index} is out of bounds for list of length {length}")

    return data[index]

