    print(safe_tuple_get(sample_tuple, 5))
    print(safe_tuple_get(sample_tuple, -1))
    print(safe_tuple_get(sample_tuple, 0))

def get_generator_element(gen, index):
    if index < 0:
        raise ValueError("Index must be non-negative")
    for i, value in enumerate(gen):
        if i == index:
            return value
    raise IndexError("Generator exhausted before reaching index")

if __name__ == '__main__':
    gen_expr = (x * x for x in range(10))
    result = get_generator_element(gen_expr, 5)
    print(result)

def get_from_generator(gen_expr, index):
    it = iter(gen_expr)
    for i in range(index + 1):
        try:
            val = next(it)
        except StopIteration:
            return None
    return val

if __name__ == '__main__':
    result = get_from_generator((x * 2 for x in range(10)), 5)
    print(result)

def get_nth_value(generator, index):
    if index < 0:
        raise IndexError("index must be non-negative")
    for current_index, value in enumerate(generator):
        if current_index == index:
            return value
    raise IndexError("index out of range")

if __name__ == '__main__':
    sample_generator = (x * x for x in range(10))
    result = get_nth_value(sample_generator, 5)
    print(result)

