    result = get_from_generator(lambda: gen_expr, 4)
    print(result)

def get_value_at_index(gen, index):
    try:
        for current_index, value in enumerate(gen):
            if current_index == index:
                return value
    except StopIteration:
        raise IndexError("index out of range")
    raise IndexError("index out of range")

