    samples = [
        ([1, 2, 3, 4], 3),
        ([1, 2], None),
        ([10, 20], -1),
        ([], -99),
        (["a", "b", "c", "d", "e"], "c"),
    ]
    for data, expected in samples:
        result = safe_extract_third(data, default=expected)
        print(result)

