def find_middle(arr):
    n = len(arr)
    if n == 0:
        return None
    mid_index = n // 2
    if n % 2 == 0:
        if mid_index - 1 >= 0:
            left = arr[mid_index - 1]
            right = arr[mid_index]
            return (left + right) / 2.0
        return right
    else:
        return arr[mid_index]

