        [7, 8, 9, 10, 11, 12, 13]
    ]

    for i, arr in enumerate(test_cases):
        try:
            result = find_middle_index_and_value(arr)
            print(f"Test case {i+1}: {arr} -> {result}")
        except ValueError as e:
            print(f"Test case {i+1}: {arr} -> Error: {e}")

