    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    if n % 2 == 1:
        return sorted_numbers[n // 2]
    else:
        lower = sorted_numbers[(n - 1) // 2]
        upper = sorted_numbers[n // 2]
        return (lower + upper) // 2

