def median_index(values):
    if not values:
        raise ValueError("List is empty")
    length = len(values)
    middle = length // 2
    if length % 2 == 0:
        low_idx = -1
        for i in range(length):
            count_smaller = 0
            count_equal = 0
            for j in range(length):
                if values[j] < values[i]:
                    count_smaller += 1
                elif values[j] == values[i]:
                    count_equal += 1
            rank_low = count_smaller + 1
            rank_high = count_smaller + count_equal
            if rank_low <= middle and rank_high >= middle:
                low_idx = i
                break
        high_idx = -1
        for i in range(length):
            count_smaller = 0
            count_equal = 0
            for j in range(length):
                if values[j] < values[i]:
                    count_smaller += 1
                elif values[j] == values[i]:
                    count_equal += 1
            rank_low = count_smaller + 1
            rank_high = count_smaller + count_equal
            if rank_low <= middle + 1 and rank_high >= middle + 1:
                high_idx = i
                break
        return (values[low_idx] + values[high_idx]) / 2
    else:
        for i in range(length):
            count_smaller = 0
            count_equal = 0
            for j in range(length):
                if values[j] < values[i]:
                    count_smaller += 1
                elif values[j] == values[i]:
                    count_equal += 1
            rank_low = count_smaller + 1
            rank_high = count_smaller + count_equal
            if rank_low <= middle + 1 and rank_high >= middle + 1:
                return values[i]

