    low = 0
    high = n - 1
    pos = low + (even_idx - low) // 2

    while True:
        pivot = lst[pos]
        lt = 0
        eq = 0
        gt = 0

        for val in lst:
            if val < pivot:
                lt += 1
            elif val == pivot:
                eq += 1
            else:
                gt += 1

        if lt < even_idx and lt + eq > even_idx:
            return pivot

        if lt + eq <= even_idx:
            target = even_idx - (lt + eq)
            high = pos + eq
            pos = low + (high - low) // 2
        else:
            low = lt + eq
            pos = low + (high - low) // 2

