    return items[middle_index]

if __name__ == '__main__':
    sample_list = [10, 20, 30, 40, 50]
    result = get_middle_value(sample_list)
    print(result)

def get_middle_value(lst):
    if not lst:
        raise ValueError("List must not be empty")
    n = len(lst)
    mid_index = n // 2
    if n % 2 == 0:
        return (lst[mid_index - 1] + lst[mid_index]) / 2
    else:
        return lst[mid_index]

if __name__ == '__main__':
    sample_data = [1, 3, 5, 7, 9]
    result = get_middle_value(sample_data)
    print(result)

def get_middle_value(values):
    if not values:
        raise ValueError("List cannot be empty")
    sorted_values = sorted(values)
    mid_index = len(sorted_values) // 2
    if len(sorted_values) % 2 == 0:
        return (sorted_values[mid_index - 1] + sorted_values[mid_index]) / 2
    return sorted_values[mid_index]

if __name__ == '__main__':
    sample_array = [7, 3, 1, 9, 5]
    result = get_middle_value(sample_array)
    print(result)

