        charset_size += 26
    if has_digit:
        charset_size += 10
    if has_special:
        charset_size += 33

    if charset_size == 0:
        return 0.0

    entropy = length * math.log2(charset_size)
    return entropy

def is_password_strong(password, threshold=60.0):
    if not isinstance(password, str):
        return False
    entropy = calculate_password_entropy(password)
    return entropy >= threshold

