    if length < 1:
        return 0

    score = 0

    if length >= 4:
        score += 1
    if length >= 8:
        score += 2
    if length >= 12:
        score += 1

    if re.search(r'[a-z]', password):
        score += 1
    if re.search(r'[A-Z]', password):
        score += 1
    if re.search(r'\d', password):
        score += 1
    if re.search(r'[^a-zA-Z0-9]', password):
