            has_lower = 1
        if 48 <= code <= 57:
            has_digit = 1
        if not (48 <= code <= 57 or 65 <= code <= 90 or 97 <= code <= 122):
            has_special = 1

    strength = (has_upper << 3) | (has_lower << 2) | (has_digit << 1) | has_special
    return strength

