import timeit

def check_password_strength(password):
    if not isinstance(password, str):
        return False
    if len(password) < 8:
        return False

    has_lower = False
    has_upper = False
    has_digit = False
    has_special = False

    lower_mask = 0
    upper_mask = 0
    digit_mask = 0
    special_mask = 0

    for char in password:
        code = ord(char)

        if 97 <= code <= 122:
            has_lower = True
            lower_mask |= (1 << (code - 97))
        elif 65 <= code <= 90:
            has_upper = True
            upper_mask |= (1 << (code - 65))
        elif 48 <= code <= 57:
            has_digit = True
            digit_mask |= (1 << (code - 48))
        else:
            has_special = True
            special_mask |= 1

    if not (has_lower and has_upper and has_digit and has_special):
        return False

    bits_lower = bin(lower_mask).count('1')
    bits_upper = bin(upper_mask).count('1')
    bits_digit = bin(digit_mask).count('1')

    entropy_bits = 0
    if bits_lower > 0:
        entropy_bits += bits_lower * 4.7
    if bits_upper > 0:
        entropy_bits += bits_upper * 4.7
    if bits_digit > 0:
        entropy_bits += bits_digit * 3.3
    if has_special:
        entropy_bits += 6.0

    penalty = 0
    i = 0
    length = len(password)
    while i < length - 2:
        if password[i] == password[i+1] == password[i+2]:
            penalty += 2
            i += 3
        elif password[i] == password[i+2] and password[i] != password[i+1]:
            penalty += 1
            i += 2
        else:
            i += 1

    if len(password) < 12:
        penalty += 2

    if has_lower and has_upper and has_digit and has_special:
        penalty -= 1

    if entropy_bits - penalty < 50:
        return False

    return True

if __name__ == '__main__':
    test_passwords = [
        "Str0ng!Pass",
        "weak",
        "alllowercase",
        "12345678",
        "My$ecur3P@ssw0rd!"
    ]

    results = []
    for pwd in test_passwords:
        result = check_password_strength(pwd)
        results.append(result)

    print(results)
    strong_count = sum(1 for r in results if r)
    print(strong_count)

import unicodedata
import string

class PasswordValidator:
    UNICODE_MIN = 0
    UNICODE_MAX = 0x10FFFF
    SURROGATE_MIN = 0xD800
    SURROGATE_MAX = 0xDFFF
    LOWER_CHARS = string.ascii_lowercase
    UPPER_CHARS = string.ascii_uppercase
    DIGIT_CHARS = string.digits

    def __init__(self, password: str):
        self.password = password
        self._is_unicode_valid = self._validate_unicode_codepoints()
        self._class_count = 0
        self._class_names = []
        if self._is_unicode_valid:
            self._class_count = self._count_character_classes()

    def _validate_unicode_codepoints(self) -> bool:
        if not isinstance(self.password, str):
            return False
        if len(self.password) == 0:
            return False
        for char in self.password:
            code_point = ord(char)
            if code_point < self.UNICODE_MIN or code_point > self.UNICODE_MAX:
                return False
            if self.SURROGATE_MIN <= code_point <= self.SURROGATE_MAX:
                return False
        return True

    def _count_character_classes(self) -> int:
        has_lower = False
        has_upper = False
        has_digit = False
        has_special = False

        for char in self.password:
            if char in self.LOWER_CHARS:
                has_lower = True
            elif char in self.UPPER_CHARS:
                has_upper = True
            elif char in self.DIGIT_CHARS:
                has_digit = True
            elif not char.isspace():
                cat = unicodedata.category(char)
                if cat.startswith('P') or cat.startswith('S') or cat.startswith('Sm'):
                    has_special = True

            if has_lower and has_upper and has_digit and has_special:
                break

        count = 0
        if has_lower:
            count += 1
        if has_upper:
            count += 1
        if has_digit:
            count += 1
        if has_special:
            count += 1
        return count

    def is_valid(self) -> bool:
        if not self._is_unicode_valid:
            return False
        return self._class_count >= 3

    def get_details(self) -> dict:
        return {
            "valid": self.is_valid(),
            "class_count": self._class_count,
            "unicode_valid": self._is_unicode_valid
        }

if __name__ == '__main__':
    test_passwords = [
        "SecurePass123",
        "weak",
        "AllUnicodeValid™️#1",
        "1234567890",
        "MixedCaseNoDigits",
        "Valid$Pass7"
    ]

    for pwd in test_passwords:
        validator = PasswordValidator(pwd)
        result = validator.get_details()
        print(f"Password: {pwd}, Valid: {result['valid']}, Classes: {result['class_count']}")

import string
import struct
import sys

def check_password_strength(password: str) -> dict:
    if not isinstance(password, str):
        return {"valid": False, "score": 0, "reason": "Not a string"}

    length = len(password)
    if length == 0:
        return {"valid": False, "score": 0, "reason": "Empty password"}

    has_lower = False
    has_upper = False
    has_digit = False
    has_special = False

    lower_mask = 0
    upper_mask = 0
    digit_mask = 0
    special_mask = 0

    ascii_table = struct.unpack('256B', b'\x00' * 256)
    for i, char_code in enumerate(password.encode('ascii', 'replace')):
        if char_code == 0:
            continue

        if 97 <= char_code <= 122:
            has_lower = True
            lower_mask |= 1
        elif 65 <= char_code <= 90:
            has_upper = True
            upper_mask |= 1
        elif 48 <= char_code <= 57:
            has_digit = True
            digit_mask |= 1
        else:
            has_special = True
            special_mask |= 1

    score = 0
    reasons = []

    if length >= 8:
        score += 1
    else:
        reasons.append("Too short")

    if has_lower:
        score += 1
    else:
        reasons.append("No lowercase")

    if has_upper:
        score += 1
    else:
        reasons.append("No uppercase")

    if has_digit:
        score += 1
    else:
        reasons.append("No digit")

    if has_special:
        score += 2
    else:
        reasons.append("No special char")

    if length >= 12:
        score += 1

    if length >= 16:
        score += 1

    valid = score >= 5

    return {
        "valid": valid,
        "score": score,
        "reasons": reasons,
        "length": length
    }

if __name__ == '__main__':
    test_passwords = [
        "Weak",
        "Strong1",
        "V3ry$trong!Pass",
        "12345678",
        "AllLowers",
        "HasSpecial#",
        "MiXeDcAsE1!",
        "Ab1"
    ]

    results = []
    for pwd in test_passwords:
        res = check_password_strength(pwd)
        results.append(f"Password: {pwd!r} | Score: {res['score']} | Valid: {res['valid']}")

    for line in results:
        print(line)

    final_result = check_password_strength("Complex99$Pass!")
    print(f"Final Check: {final_result}")

import unicodedata
import string

class PasswordValidator:
    UNICODE_MAX = 0x10FFFF
    SURROGATE_START = 0xD800
    SURROGATE_END = 0xDFFF
    ASCII_DIGITS = string.digits
    ASCII_LOWERCASE = string.ascii_lowercase
    ASCII_UPPERCASE = string.ascii_uppercase
    SPECIAL_CHARS = set(string.punctuation)

    def __init__(self, password: str):
        self.password = password
        self._is_unicode_valid = self._verify_unicode()
        self._class_count = 0
        if self._is_unicode_valid:
            self._class_count = self._count_character_classes()

    def _verify_unicode(self) -> bool:
        if not isinstance(self.password, str):
            return False
        for char in self.password:
            code_point = ord(char)
            if code_point > self.UNICODE_MAX:
                return False
            if self.SURROGATE_START <= code_point <= self.SURROGATE_END:
                return False
        return True

    def _count_character_classes(self) -> int:
        flags = {
            'digit': False,
            'lower': False,
            'upper': False,
            'special': False
        }

        for char in self.password:
            if char in self.ASCII_DIGITS:
                flags['digit'] = True
            elif char in self.ASCII_LOWERCASE:
                flags['lower'] = True
            elif char in self.ASCII_UPPERCASE:
                flags['upper'] = True
            elif char in self.SPECIAL_CHARS:
                flags['special'] = True
            elif unicodedata.category(char).startswith('L'):
                flags['lower'] = True
            elif unicodedata.category(char).startswith('Nd'):
                flags['digit'] = True

        return sum(flags.values())

    def is_valid(self) -> bool:
        if not self._is_unicode_valid:
            return False
        return self._class_count >= 3

    def get_class_count(self) -> int:
        return self._class_count

    def is_unicode_valid(self) -> bool:
        return self._is_unicode_valid

if __name__ == '__main__':
    sample_passwords = [
        "SecurePass123!",
        "weak",
        "Mix3dChars#",
        "InvalidSurrogate\uDBFF\uDC00",
        "Привет123!",
        "12345678",
        "ALLUPPERCASE1"
    ]

    for pwd in sample_passwords:
        validator = PasswordValidator(pwd)
        print(f"Password: {pwd!r} | Valid: {validator.is_valid()} | Classes: {validator.get_class_count()} | UnicodeOK: {validator.is_unicode_valid()}")

import string
import math
import json

class PasswordEntropyResult:
    def __init__(self, entropy_bits: float, length: int, char_sets_used: int, is_valid: bool, reasons: list):
        self.entropy_bits = entropy_bits
        self.length = length
        self.char_sets_used = char_sets_used
        self.is_valid = is_valid
        self.reasons = reasons

    def to_dict(self) -> dict:
        return {
            "entropy_bits": self.entropy_bits,
            "length": self.length,
            "char_sets_used": self.char_sets_used,
            "is_valid": self.is_valid,
            "reasons": self.reasons
        }

def evaluate_password_entropy(password: str, min_entropy_bits: float = 60.0, min_length: int = 8) -> PasswordEntropyResult:
    if not isinstance(password, str):
        return PasswordEntropyResult(
            entropy_bits=0.0,
            length=0,
            char_sets_used=0,
            is_valid=False,
            reasons=["Password must be a string"]
        )

    length = len(password)
    char_sets_used = 0
    pool_size = 0

    if any(c in string.ascii_lowercase for c in password):
        pool_size += 26
        char_sets_used += 1
    if any(c in string.ascii_uppercase for c in password):
        pool_size += 26
        char_sets_used += 1
    if any(c in string.digits for c in password):
        pool_size += 10
        char_sets_used += 1
    if any(c in string.punctuation for c in password):
        pool_size += len(string.punctuation)
        char_sets_used += 1

    if length == 0:
        entropy_bits = 0.0
    else:
        if pool_size > 0:
            entropy_bits = length * math.log2(pool_size)
        else:
            entropy_bits = 0.0

    reasons = []
    is_valid = True

    if length < min_length:
        reasons.append(f"Length {length} is less than minimum {min_length}")
        is_valid = False

    if entropy_bits < min_entropy_bits:
        reasons.append(f"Entropy {entropy_bits:.2f} bits is below threshold {min_entropy_bits} bits")
        is_valid = False

    if char_sets_used < 3:
        reasons.append(f"Uses only {char_sets_used} character sets, expected at least 3")
        is_valid = False

    return PasswordEntropyResult(
        entropy_bits=entropy_bits,
        length=length,
        char_sets_used=char_sets_used,
        is_valid=is_valid,
        reasons=reasons
    )

if __name__ == '__main__':
    password = "MyP@ssw0rd123!"
    result = evaluate_password_entropy(password)
    print(json.dumps(result.to_dict(), indent=2))

import hashlib
import struct

def check_password_strength(password: str) -> dict:
    if not password:
        return {"score": 0, "criteria_met": False}

    length = len(password)
    bits = [bit for bit in password.encode('utf-8')]

    upper_mask = 0x00
    lower_mask = 0x00
    digit_mask = 0x00
    special_mask = 0x00

    for byte_val in bits:
        if 65 <= byte_val <= 90:
            upper_mask |= 1
        elif 97 <= byte_val <= 122:
            lower_mask |= 1
        elif 48 <= byte_val <= 57:
            digit_mask |= 1
        elif (33 <= byte_val <= 47) or (58 <= byte_val <= 64) or (91 <= byte_val <= 96) or (123 <= byte_val <= 126):
            special_mask |= 1

    has_upper = bool(upper_mask)
    has_lower = bool(lower_mask)
    has_digit = bool(digit_mask)
    has_special = bool(special_mask)

    criteria_met = has_upper and has_lower and has_digit and has_special

    score = 0
    if has_upper:
        score += 25
    if has_lower:
        score += 25
    if has_digit:
        score += 25
    if has_special:
        score += 25

    if length >= 12:
        score += 25
    elif length >= 8:
        score += 10

    if length >= 16:
        score += 25

    entropy_est = length * 3.3219280948873626 
    if has_upper:
        entropy_est += 4.700439718141093 
    if has_lower:
        entropy_est += 4.700439718141093 
    if has_digit:
        entropy_est += 3.3219280948873626 
    if has_special:
        entropy_est += 5.700439718141093 

    normalized_score = min(100, score)

    result = {
        "score": normalized_score,
        "criteria_met": criteria_met and length >= 8
    }

    return result

def evaluate_password_hardcoded() -> dict:
    sample_password = "Str0ng!Pass#2024"
    result = check_password_strength(sample_password)
    return result

if __name__ == '__main__':
    res = evaluate_password_hardcoded()
    print(res)

import unicodedata

class PasswordValidator:
    def __init__(self, password):
        self.password = password

    def is_unicode_valid(self):
        for char in self.password:
            cp = ord(char)
            if cp > 0x10FFFF:
                return False
            if 0xD800 <= cp <= 0xDFFF:
                return False
        return True

    def validate(self):
        if not self.is_unicode_valid():
            return False

        has_upper = any(char.isupper() for char in self.password)
        has_lower = any(char.islower() for char in self.password)
        has_digit = any(char.isdigit() for char in self.password)

        has_symbol = False
        for char in self.password:
            if not char.isalnum() and not char.isspace():
                has_symbol = True
                break

        classes_present = 0
        if has_upper:
            classes_present += 1
        if has_lower:
            classes_present += 1
        if has_digit:
            classes_present += 1
        if has_symbol:
            classes_present += 1

        return classes_present >= 3

if __name__ == '__main__':
    validator1 = PasswordValidator("Hello123!")
    print(validator1.validate())

    validator2 = PasswordValidator("hello123")
    print(validator2.validate())

    validator3 = PasswordValidator("HELLO!@#")
    print(validator3.validate())

    validator4 = PasswordValidator("")
    print(validator4.validate())

    validator5 = PasswordValidator("Abc")
    print(validator5.validate())

import string
import math
import json

def evaluate_password_entropy(password: str, min_length: int = 8, min_entropy_bits: float = 60.0) -> dict:
    if not isinstance(password, str):
        return {"valid": False, "reasons": ["Password must be a string"]}

    reasons = []

    if len(password) < min_length:
        reasons.append(f"Password length {len(password)} is less than minimum {min_length}")

    entropy_bits = 0.0
    charset_size = 0

    if any(c in string.ascii_lowercase for c in password):
        charset_size += 26
    if any(c in string.ascii_uppercase for c in password):
        charset_size += 26
    if any(c in string.digits for c in password):
        charset_size += 10
    if any(c in string.punctuation for c in password):
        charset_size += len(string.punctuation)

    if charset_size > 0:
        entropy_bits = len(password) * math.log2(charset_size)

    if entropy_bits < min_entropy_bits:
        reasons.append(f"Entropy {entropy_bits:.2f} bits is less than required {min_entropy_bits} bits")

    valid = len(reasons) == 0

    return {
        "valid": valid,
        "entropy_bits": round(entropy_bits, 2),
        "password_length": len(password),
        "charset_size": charset_size,
        "reasons": reasons
    }

if __name__ == '__main__':
    sample_password = "Str0ng!Pass#99"
    result = evaluate_password_entropy(sample_password)
    print(json.dumps(result, indent=2))

    weak_password = "abc"
    weak_result = evaluate_password_entropy(weak_password)
    print(json.dumps(weak_result, indent=2))

import string
import math
import enum

class PasswordEvaluationStatus(enum.Enum):
    VALID = "valid"
    TOO_SHORT = "too_short"
    TOO_SIMPLE = "too_simple"
    TOO_MONOTONOUS = "too_monotonous"

class PasswordEvaluationResult:
    def __init__(self, status: PasswordEvaluationStatus, entropy: float, details: dict):
        self.status = status
        self.entropy = entropy
        self.details = details

    def __repr__(self):
        return (
            f"PasswordEvaluationResult("
            f"status={self.status.value}, "
            f"entropy={self.entropy:.2f}, "
            f"details={self.details})"
        )

def evaluate_password_entropy(
    password: str,
    min_length: int = 8,
    min_entropy: float = 50.0,
    min_unique_chars: int = 4,
    max_repetition_ratio: float = 0.5,
) -> PasswordEvaluationResult:
    length = len(password)
    if length == 0:
        return PasswordEvaluationResult(
            PasswordEvaluationStatus.TOO_SHORT,
            0.0,
            {"reason": "empty_password", "length": 0},
        )

    charset_size = 0
    if any(c in string.ascii_lowercase for c in password):
        charset_size += 26
    if any(c in string.ascii_uppercase for c in password):
        charset_size += 26
    if any(c in string.digits for c in password):
        charset_size += 10
    if any(c in string.punctuation for c in password):
        charset_size += 32

    if charset_size == 0:
        return PasswordEvaluationResult(
            PasswordEvaluationStatus.TOO_SIMPLE,
            0.0,
            {"reason": "invalid_characters", "length": length},
        )

    entropy = length * math.log2(charset_size) if charset_size > 1 else 0.0

    if length < min_length:
        return PasswordEvaluationResult(
            PasswordEvaluationStatus.TOO_SHORT,
            entropy,
            {
                "reason": "too_short",
                "length": length,
                "min_length": min_length,
                "entropy": entropy,
            },
        )

    unique_chars = len(set(password))
    if unique_chars < min_unique_chars:
        return PasswordEvaluationResult(
            PasswordEvaluationStatus.TOO_SIMPLE,
            entropy,
            {
                "reason": "too_simple",
                "unique_chars": unique_chars,
                "min_unique_chars": min_unique_chars,
                "entropy": entropy,
            },
        )

    max_repeat = 1
    current_repeat = 1
    for i in range(1, length):
        if password[i] == password[i - 1]:
            current_repeat += 1
            if current_repeat > max_repeat:
                max_repeat = current_repeat
        else:
            current_repeat = 1

    repetition_ratio = max_repeat / length
    if repetition_ratio > max_repetition_ratio:
        return PasswordEvaluationResult(
            PasswordEvaluationStatus.TOO_MONOTONOUS,
            entropy,
            {
                "reason": "too_monotonous",
                "max_repetition": max_repeat,
                "repetition_ratio": repetition_ratio,
                "entropy": entropy,
            },
        )

    if entropy < min_entropy:
        return PasswordEvaluationResult(
            PasswordEvaluationStatus.TOO_SIMPLE,
            entropy,
            {
                "reason": "insufficient_entropy",
                "entropy": entropy,
                "min_entropy": min_entropy,
            },
        )

    return PasswordEvaluationResult(
        PasswordEvaluationStatus.VALID,
        entropy,
        {
            "reason": "accepted",
            "length": length,
            "charset_size": charset_size,
            "unique_chars": unique_chars,
            "entropy": entropy,
        },
    )

if __name__ == "__main__":
    test_passwords = [
        "abc123",
        "MyP@ssw0rd!",
        "a" * 10,
        "short",
        "Valid!Str1ng",
    ]

    for pwd in test_passwords:
        result = evaluate_password_entropy(pwd)
        print(result)

import math
import string

class PasswordEntropyResult:
    def __init__(self, valid: bool, entropy: float, failure_reasons: list):
        self.valid = valid
        self.entropy = entropy
        self.failure_reasons = failure_reasons

    def __str__(self):
        status = "Valid" if self.valid else "Invalid"
        reasons_str = ", ".join(self.failure_reasons) if self.failure_reasons else "None"
        return f"Password: {status}, Entropy: {self.entropy:.2f} bits, Reasons: {reasons_str}"

    def __repr__(self):
        return (f"PasswordEntropyResult(valid={self.valid}, "
                f"entropy={self.entropy:.2f}, "
                f"failure_reasons={self.failure_reasons})")

def evaluate_password(password: str, threshold: float = 60.0) -> PasswordEntropyResult:
    if not isinstance(password, str):
        return PasswordEntropyResult(False, 0.0, ["Password must be a string"])

    failure_reasons = []
    min_length = 8

    if len(password) < min_length:
        failure_reasons.append(f"Too short (min {min_length} chars)")

    has_lower = any(c in string.ascii_lowercase for c in password)
    has_upper = any(c in string.ascii_uppercase for c in password)
    has_digit = any(c in string.digits for c in password)
    has_special = any(c in string.punctuation for c in password)

    diversity_count = sum([has_lower, has_upper, has_digit, has_special])

    if diversity_count < 2:
        failure_reasons.append("Lack of character diversity")

    if len(password) == 0:
        entropy = 0.0
    else:
        pool_size = 0
        if has_lower:
            pool_size += 26
        if has_upper:
            pool_size += 26
        if has_digit:
            pool_size += 10
        if has_special:
            pool_size += 32

        if pool_size == 0:
            entropy = 0.0
        else:
            entropy = len(password) * math.log2(pool_size)

    if entropy < threshold:
        failure_reasons.append(f"Entropy below threshold ({entropy:.2f} < {threshold})")

    valid = len(failure_reasons) == 0
    return PasswordEntropyResult(valid, entropy, failure_reasons)

if __name__ == '__main__':
    test_cases = [
        "short",
        "StrongPass123!",
        "password",
        "AllLowercase1",
        ""
    ]

    for pwd in test_cases:
        result = evaluate_password(pwd)
        print(result)

import unicodedata

VALID_UNICODE_MAX = 0x10FFFF
SURROGATE_START = 0xD800
SURROGATE_END = 0xDFFF

class PasswordVerifier:
    def __init__(self, text):
        self.text = text
        self._unicode_ok = self._verify_unicode()
        self._class_count = self._count_classes() if self._unicode_ok else 0

    def _verify_unicode(self):
        for char in self.text:
            cp = ord(char)
            if cp > VALID_UNICODE_MAX:
                return False
            if SURROGATE_START <= cp <= SURROGATE_END:
                return False
        return True

    def _count_classes(self):
        found_upper = False
        found_lower = False
        found_digit = False
        found_special = False

        for char in self.text:
            cat = unicodedata.category(char)
            if cat.startswith('Lu') and not found_upper:
                found_upper = True
            elif cat.startswith('Ll') and not found_lower:
                found_lower = True
            elif cat.startswith('Nd') and not found_digit:
                found_digit = True
            elif not cat.startswith(('L', 'N', 'Z')) and not found_special:
                found_special = True

        if found_upper and found_lower and found_digit and found_special:
            return 4
        return sum([found_upper, found_lower, found_digit, found_special])

    def is_valid(self):
        return self._class_count >= 3

if __name__ == '__main__':
    sample1 = PasswordVerifier("StrongP@ss1")
    print(sample1.is_valid())
    sample2 = PasswordVerifier("weak")
    print(sample2.is_valid())
