    print(sample3.is_valid())
    sample4 = PasswordVerifier("Abcdefgh")
    print(sample4.is_valid())
    sample5 = PasswordVerifier("!@#$%^&*")
    print(sample5.is_valid())
    sample6 = PasswordVerifier("P@ssword")
    print(sample6.is_valid())

def check_password_strength(password):
    has_upper = 0
    has_lower = 0
    has_digit = 0
    has_symbol = 0
    length = len(password)

    if length < 12:
        return False

    for char in password:
        code = ord(char)
        if (code >= 65) and (code <= 90):
            has_upper = 1
        elif (code >= 97) and (code <= 122):
            has_lower = 1
        elif (code >= 48) and (code <= 57):
            has_digit = 1
        else:
            has_symbol = 1

    mask = (has_upper << 3) | (has_lower << 2) | (has_digit << 1) | has_symbol
    required_mask = 0b1111

    return (mask & required_mask) == required_mask

if __name__ == '__main__':
    test_string = "SecureP@ssw0rd!"
    result = check_password_strength(test_string)
    print(result)

import math
import string
import collections

def evaluate_password_entropy(password, threshold=60.0):
    if not isinstance(password, str):
        return {
            'valid': False,
            'entropy': 0.0,
            'length': 0,
            'character_diversity': 0,
            'failures': ['Password must be a string']
        }

    length = len(password)

    if length == 0:
        return {
            'valid': False,
            'entropy': 0.0,
            'length': 0,
            'character_diversity': 0,
            'failures': ['Password is empty']
        }

    has_lower = any(c in string.ascii_lowercase for c in password)
    has_upper = any(c in string.ascii_uppercase for c in password)
    has_digit = any(c in string.digits for c in password)
    has_special = any(c in string.punctuation for c in password)

    pool_size = 0
    if has_lower:
        pool_size += 26
    if has_upper:
        pool_size += 26
    if has_digit:
        pool_size += 10
    if has_special:
        pool_size += 32

    if pool_size == 0:
        return {
            'valid': False,
            'entropy': 0.0,
            'length': length,
            'character_diversity': 0,
            'failures': ['No recognizable character types found']
        }

    entropy = length * math.log2(pool_size)

    unique_chars = len(set(password))
    character_diversity = unique_chars / length

    failures = []

    if entropy < threshold:
        failures.append(f'Entropy {entropy:.2f} bits is below threshold {threshold} bits')

    if length < 8:
        failures.append('Password length is less than 8 characters')

    if character_diversity < 0.5:
        failures.append('Low character diversity ratio')

    if not has_lower:
        failures.append('Missing lowercase letters')
    if not has_upper:
        failures.append('Missing uppercase letters')
    if not has_digit:
        failures.append('Missing digits')
    if not has_special:
        failures.append('Missing special characters')

    is_valid = len(failures) == 0

    return {
        'valid': is_valid,
        'entropy': round(entropy, 2),
        'length': length,
        'character_diversity': round(character_diversity, 4),
        'failures': failures
    }

if __name__ == '__main__':
    sample_password = "MyP@ssw0rd!"
    result = evaluate_password_entropy(sample_password)
    print(result)

def check_password_strength(password):
    length_ok = len(password) >= 12
    has_upper = False
    has_lower = False
    has_digit = False
    has_special = False

    special_chars = set("!@#$%^&*()_+-=[]{}|;:',.<>?/~`")

    for char in password:
        code = ord(char)
        if 65 <= code <= 90:
            has_upper = True
        elif 97 <= code <= 122:
            has_lower = True
        elif 48 <= code <= 57:
            has_digit = True
        elif char in special_chars:
            has_special = True

    strength_bits = 0
    if length_ok:
        strength_bits |= 1
    if has_upper:
        strength_bits |= 2
    if has_lower:
        strength_bits |= 4
    if has_digit:
        strength_bits |= 8
    if has_special:
        strength_bits |= 16

    is_strong = (strength_bits == 31)
    return strength_bits, is_strong

