import string

def check_password_strength(password):
    if not password:
        return False
    has_lower = 0
    has_upper = 0
    has_digit = 0
    has_special = 0
    lower_set = set(string.ascii_lowercase)
    upper_set = set(string.ascii_uppercase)
    digit_set = set(string.digits)
    special_set = set(string.punctuation)
    for char in password:
        if char in lower_set:
            has_lower = 1
        elif char in upper_set:
            has_upper = 1
        elif char in digit_set:
            has_digit = 1
        elif char in special_set:
            has_special = 1
    mask = 0
    if has_lower:
        mask |= 1
    if has_upper:
        mask |= 2
    if has_digit:
        mask |= 4
    if has_special:
        mask |= 8
    if len(password) < 12:
        return False
    if mask != 15:
        return False
    consecutive_count = 0
    for i in range(len(password) - 1):
        if ord(password[i]) + 1 == ord(password[i + 1]):
            consecutive_count += 1
        else:
            consecutive_count = 0
        if consecutive_count >= 3:
            return False
    return True

if __name__ == '__main__':
    test_string = "SecureP@ssw0rd12!"
    result = check_password_strength(test_string)
    print(result)

import unicodedata

class PasswordSecurityChecker:
    VALID_CP_MAX = 0x10FFFF
    SURROGATE_START = 0xD800
    SURROGATE_END = 0xDFFF
    MIN_CLASSES = 3

    def __init__(self, secret: str):
        self.secret = secret

    def _is_unicode_safe(self) -> bool:
        for char in self.secret:
            cp = ord(char)
            if cp > self.VALID_CP_MAX:
                return False
            if self.SURROGATE_START <= cp <= self.SURROGATE_END:
                return False
        return True

    def _detect_classes(self) -> int:
        categories = unicodedata.category
        has_upper = False
        has_lower = False
        has_digit = False
        has_symbol = False

        for char in self.secret:
            cat = categories(char)
            if cat.startswith('Lu'):
                has_upper = True
            elif cat.startswith('Ll'):
                has_lower = True
            elif cat.startswith('Nd'):
                has_digit = True
            elif cat.startswith('S') or cat.startswith('P'):
                has_symbol = True

            if has_upper and has_lower and has_digit and has_symbol:
                return 4

        count = 0
        if has_upper:
            count += 1
        if has_lower:
            count += 1
        if has_digit:
            count += 1
        if has_symbol:
            count += 1

        return count

    def verify(self) -> bool:
        if not self._is_unicode_safe():
            return False
        classes_found = self._detect_classes()
        return classes_found >= self.MIN_CLASSES

if __name__ == '__main__':
    samples = [
        "Abc123!",
        "password",
        "ABC123",
        "a1b2c3!@#",
        "Hello World 123",
        "P@ssw0rd",
        "simple",
        "C0mpl3x!ty",
    ]

    results = []
    for sample in samples:
        checker = PasswordSecurityChecker(sample)
        results.append((sample, checker.verify()))

    for password, is_valid in results:
        print(password, is_valid)

import unicodedata
import string

class PasswordValidator:
    VALID_UNICODE_MAX = 0x10FFFF
    SURROGATE_LOW = 0xD800
    SURROGATE_HIGH = 0xDFFF

    def __init__(self, password):
        self.password = password

    def _is_unicode_valid(self):
        for char in self.password:
            code = ord(char)
            if code > self.VALID_UNICODE_MAX:
                return False
            if self.SURROGATE_LOW <= code <= self.SURROGATE_HIGH:
                return False
        return True

    def _count_categories(self):
        has_upper = False
        has_lower = False
        has_digit = False
        has_symbol = False

        for char in self.password:
            category = unicodedata.category(char)

            if category.startswith('Lu'):
                has_upper = True
            elif category.startswith('Ll') or category.startswith('Lt') or category.startswith('Lm') or category.startswith('Lo'):
                has_lower = True
            elif category.startswith('Nd'):
                has_digit = True
            else:
                has_symbol = True

        count = sum([has_upper, has_lower, has_digit, has_symbol])
        return count

    def validate(self):
        if not self._is_unicode_valid():
            return False
        return self._count_categories() >= 3

