    print(f'Bitwise check ({iterations} iterations): {bitwise_time:.6f} seconds')
    print(f'Speedup: {detailed_time / bitwise_time:.2f}x')

import string
import math
from dataclasses import dataclass
from typing import List

@dataclass
class PasswordAnalysis:
    is_valid: bool
    entropy: float
    reasons: List[str]

def evaluate_password_entropy(password: str, min_length: int = 12, min_entropy: float = 50.0) -> PasswordAnalysis:
    reasons = []
    if len(password) < min_length:
        reasons.append(f"Length {len(password)} is less than required {min_length}")

    has_lower = any(c in string.ascii_lowercase for c in password)
    has_upper = any(c in string.ascii_uppercase for c in password)
    has_digit = any(c in string.digits for c in password)
    has_special = any(c in string.punctuation for c in password)

    char_set_size = 0
    if has_lower:
        char_set_size += 26
    if has_upper:
        char_set_size += 26
    if has_digit:
        char_set_size += 10
    if has_special:
        char_set_size += 33

    if char_set_size < 36:
        reasons.append("Character diversity is too low")

    if char_set_size > 0:
        entropy = len(password) * math.log2(char_set_size)
    else:
        entropy = 0.0
        reasons.append("No valid characters found")

    if entropy < min_entropy:
        reasons.append(f"Entropy {entropy:.2f} is below required {min_entropy}")

    return PasswordAnalysis(
        is_valid=len(reasons) == 0,
        entropy=entropy,
        reasons=reasons
    )

if __name__ == '__main__':
    test_password = "MySecureP@ssw0rd123"
    result = evaluate_password_entropy(test_password, 12, 50.0)
    print(result)

    weak_password = "abc"
    weak_result = evaluate_password_entropy(weak_password, 12, 50.0)
    print(weak_result)

import unicodedata
import re

class PasswordValidator:
    VALID_MAX = 0x10FFFF
    SURROGATE_START = 0xD800
    SURROGATE_END = 0xDFFF
    MIN_CLASSES = 3

    def __init__(self, password: str):
        self.password = password
        self.is_valid = self._run_validation()

    def _run_validation(self) -> bool:
        if not self._check_unicode_support():
            return False
        return self._check_character_classes() >= self.MIN_CLASSES

    def _check_unicode_support(self) -> bool:
        for char in self.password:
            code = ord(char)
            if code > self.VALID_MAX:
                return False
            if self.SURROGATE_START <= code <= self.SURROGATE_END:
                return False
        return True

    def _check_character_classes(self) -> int:
        has_lower = False
        has_upper = False
        has_digit = False
        has_special = False

        for char in self.password:
            if not has_lower:
                if char.islower():
                    has_lower = True
            if not has_upper:
                if char.isupper():
                    has_upper = True
            if not has_digit:
                if char.isdigit():
                    has_digit = True
            if not has_special:
                if not char.isalnum():
                    has_special = True
            if has_lower and has_upper and has_digit and has_special:
                return 4

        return sum([has_lower, has_upper, has_digit, has_special])

if __name__ == '__main__':
    samples = [
        "Short",
        "123456",
        "P@ssw0rd!",
        "abcdef",
        "Abc!123",
        "NoSpecial123",
        "NoDigits!abc",
        "NOLOWERCASE123!",
        "ALLGOOD123!",
        "üñíçödéP@ss1",
        "\uD800",
        "Valid_Unicode_123!",
        "JustLetters",
        "123Numbers",
        "SymbolsOnly!!!",
        "A1!b",
    ]

    for sample in samples:
        validator = PasswordValidator(sample)
        print(f"Password: {repr(sample)}, Valid: {validator.is_valid}")

import math
import string

PASSWORD_MIN_LENGTH = 8
CHAR_SETS = (string.ascii_lowercase, string.ascii_uppercase, string.digits, string.punctuation)

class PasswordEvaluationResult:
    def __init__(self, is_valid, entropy_bits, length, diversity_count, failure_reasons):
        self.is_valid = is_valid
        self.entropy_bits = entropy_bits
        self.length = length
        self.diversity_count = diversity_count
        self.failure_reasons = failure_reasons

    def __repr__(self):
        return (
            f"PasswordEvaluationResult(is_valid={self.is_valid}, "
            f"entropy_bits={self.entropy_bits:.2f}, "
            f"length={self.length}, "
            f"diversity_count={self.diversity_count}, "
            f"failure_reasons={self.failure_reasons})"
        )

def evaluate_password_entropy(password):
    length = len(password)
    diversity_count = 0
    for char_set in CHAR_SETS:
        if any(char in char_set for char in password):
            diversity_count += 1

    charset_size = 0
    for char_set in CHAR_SETS:
        if any(char in char_set for char in password):
            charset_size += len(char_set)

    if charset_size == 0:
        entropy_bits = 0.0
    else:
        entropy_bits = length * math.log2(charset_size)

    failure_reasons = []
    if length < PASSWORD_MIN_LENGTH:
        failure_reasons.append("too_short")
    if diversity_count < 2:
        failure_reasons.append("insufficient_character_diversity")
    if entropy_bits < 60:
        failure_reasons.append("low_entropy")

    is_valid = (length >= PASSWORD_MIN_LENGTH and diversity_count >= 2 and entropy_bits >= 60)

    return PasswordEvaluationResult(
        is_valid=is_valid,
        entropy_bits=entropy_bits,
        length=length,
        diversity_count=diversity_count,
        failure_reasons=failure_reasons
    )

if __name__ == '__main__':
    result = evaluate_password_entropy("Str0ng!Pass#2023")
    print(result)

    weak_result = evaluate_password_entropy("abc")
    print(weak_result)

