import math
import string
import json
from typing import List, Dict, Any

class PasswordEntropyResult:
    def __init__(self, is_valid: bool, entropy_bits: float, reasons: List[str], details: Dict[str, Any]):
        self.is_valid = is_valid
        self.entropy_bits = entropy_bits
        self.reasons = reasons
        self.details = details

    def to_dict(self) -> Dict[str, Any]:
        return {
            "is_valid": self.is_valid,
            "entropy_bits": round(self.entropy_bits, 2),
            "failure_reasons": self.reasons,
            "character_diversity": {
                "length": self.details["length"],
                "unique_chars": self.details["unique_chars"],
                "has_uppercase": self.details["has_uppercase"],
                "has_lowercase": self.details["has_lowercase"],
                "has_digits": self.details["has_digits"],
                "has_special": self.details["has_special"]
            },
            "pool_size": self.details["pool_size"]
        }

def evaluate_password_entropy(password: str, min_entropy: float = 50.0) -> PasswordEntropyResult:
    reasons = []
    length = len(password)
    unique_chars = len(set(password))

    has_upper = any(c in string.ascii_uppercase for c in password)
    has_lower = any(c in string.ascii_lowercase for c in password)
    has_digit = any(c in string.digits for c in password)
    has_special = any(c in string.punctuation for c in password)

    pool_size = 0
    if has_upper:
        pool_size += 26
    if has_lower:
        pool_size += 26
    if has_digit:
        pool_size += 10
    if has_special:
        pool_size += 32

    if pool_size == 0:
        entropy = 0.0
    else:
        entropy = length * math.log2(pool_size) if length > 0 else 0.0

    if length < 8:
        reasons.append("Password length is less than 8 characters")

    if not has_upper:
        reasons.append("Missing uppercase letters")
    if not has_lower:
        reasons.append("Missing lowercase letters")
    if not has_digit:
        reasons.append("Missing digits")
    if not has_special:
        reasons.append("Missing special characters")

    if entropy < min_entropy:
        reasons.append(f"Entropy {round(entropy, 2)} bits is below the required {min_entropy} bits")

    is_valid = len(reasons) == 0

    details = {
        "length": length,
        "unique_chars": unique_chars,
        "has_uppercase": has_upper,
        "has_lowercase": has_lower,
        "has_digits": has_digit,
        "has_special": has_special,
        "pool_size": pool_size
    }

    return PasswordEntropyResult(is_valid, entropy, reasons, details)

if __name__ == "__main__":
    sample_password = "SecureP@ssw0rd123"
    result = evaluate_password_entropy(sample_password)
    print(json.dumps(result.to_dict(), indent=4))

import unicodedata

MAX_CODE_POINT = 0x10FFFF
SURROGATE_START = 0xD800
SURROGATE_END = 0xDFFF

def is_unicode_safe(char):
    code = ord(char)
    return code <= MAX_CODE_POINT and not (SURROGATE_START <= code <= SURROGATE_END)

def get_category_flags(password):
    has_upper = False
    has_lower = False
    has_digit = False
    has_symbol = False
    for char in password:
        cat = unicodedata.category(char)
        if cat.startswith('Lu'):
            has_upper = True
        elif cat.startswith('Ll'):
            has_lower = True
        elif cat.startswith('Nd'):
            has_digit = True
        elif not cat.startswith('L') and not cat.startswith('N') and not cat.startswith('Z'):
            has_symbol = True
    return has_upper, has_lower, has_digit, has_symbol

def validate_password_strength(password):
    if not isinstance(password, str):
        return False
    if not all(is_unicode_safe(c) for c in password):
        return False
    u, l, d, s = get_category_flags(password)
    count = sum([u, l, d, s])
    return count >= 3

class PasswordCheck:
    def __init__(self, pwd):
        self.result = validate_password_strength(pwd)

if __name__ == '__main__':
    samples = ["Abc123!", "simple", "12345", "A_b_c!"]
    for s in samples:
        obj = PasswordCheck(s)
        print(obj.result)

import unicodedata

class PasswordValidator:
    def __init__(self):
        self.classes = ["upper", "lower", "digit", "symbol"]

    def _has_upper(self, pwd):
        for char in pwd:
            if unicodedata.category(char).startswith('Lu'):
                return True
        return False

    def _has_lower(self, pwd):
        for char in pwd:
            if unicodedata.category(char).startswith('Ll'):
                return True
        return False

    def _has_digit(self, pwd):
        for char in pwd:
            if unicodedata.category(char).startswith('Nd'):
                return True
        return False

    def _has_symbol(self, pwd):
        for char in pwd:
            cat = unicodedata.category(char)
            if cat.startswith('P') or cat.startswith('S') or cat.startswith('Z'):
                return True
        return False

    def validate(self, password):
        if not password:
            return False

        has_unicode = False
        for char in password:
            if ord(char) > 127:
                has_unicode = True
                break

        if not has_unicode:
            return False

        found_classes = 0
        if self._has_upper(password):
            found_classes += 1
        if self._has_lower(password):
            found_classes += 1
        if self._has_digit(password):
            found_classes += 1
        if self._has_symbol(password):
            found_classes += 1

        return found_classes >= 3

if __name__ == '__main__':
    validator = PasswordValidator()
    test_pwd = "Привет1!@#"
    result = validator.validate(test_pwd)
    print(result)
    test_pwd2 = "HelloWorld123"
    result2 = validator.validate(test_pwd2)
    print(result2)

def check_password_strength(password):
    length = len(password)
    if length < 12:
        return False
    has_upper = False
    has_lower = False
    has_digit = False
    has_special = False
    for char in password:
        code = ord(char)
        if 65 <= code <= 90:
            has_upper = True
        elif 97 <= code <= 122:
            has_lower = True
        elif 48 <= code <= 57:
            has_digit = True
        else:
            has_special = True
        if has_upper and has_lower and has_digit and has_special:
            return True
    return False

