        range(80, 90): 'B',
        range(70, 80): 'C',
        range(60, 70): 'D',
        range(-1, 60): 'F'
    }
    result = []
    for score in raw_scores:
        for grade_range, letter in score_map.items():
            if score in grade_range:
                result.append(letter)
                break
    return result

