def scores_to_grades(scores):
    grade_boundaries = [
        (90, 'A'),
        (80, 'B'),
        (70, 'C'),
        (60, 'D'),
        (0, 'F')
    ]

    def get_grade(score):
        return next(
            grade for threshold, grade in grade_boundaries if score >= threshold
        )

    return [get_grade(score) for score in scores]

