def is_sequential(password, length=3):
    if len(password) < length:
        return False
    for i in range(len(password) - length + 1):
        sequential = True
        for j in range(1, length):
            if ord(password[i + j]) != ord(password[i + j - 1]) + 1:
                sequential = False
                break
        if sequential:
            return True
    return False

def validate_password_strength(password):
    if not password:
