            has_upper = True
        elif char.islower():
            has_lower = True
        elif char.isdigit():
            has_digit = True
        else:
            has_special = True
    if not (has_upper and has_lower and has_digit and has_special):
        return False
    if is_sequential(password):
        return False
    return True

