    for pwd in sample_passwords:
        validation_result = validate_password_strength(pwd)
        print(f"Password: {pwd}, Valid: {validation_result['is_valid']}, Reasons: {validation_result['reasons']}")

class GradeCalculator:
    def __init__(self, grading_scale):
        self.grading_scale = grading_scale

    def determine_grade(self, score):
        if not isinstance(score, (int, float)):
            raise TypeError("Score must be a number")
        if score < 0 or score > 100:
            raise ValueError("Score must be between 0 and 100")
        for min_score, grade in sorted(self.grading_scale.items(), reverse=True):
            if score >= min_score:
                return grade
        return "F"

