def calculate_grades(scores: list[int] | list[float]) -> list[str]:
    if not scores:
        return []

    min_score = min(scores)
    max_score = max(scores)
    score_range = max_score - min_score

    if score_range == 0:
        return ["A"] * len(scores)

    grades = []
    for score in scores:
        normalized = (score - min_score) / score_range
        if normalized >= 0.9:
            grades.append("A")
        elif normalized >= 0.8:
            grades.append("B")
        elif normalized >= 0.7:
            grades.append("C")
        elif normalized >= 0.6:
            grades.append("D")
        else:
            grades.append("F")

    return grades

