def convert_scores_to_grades(scores):
    mapping = [
        (90, 'A'),
        (80, 'B'),
        (70, 'C'),
        (60, 'D'),
        (0, 'F')
    ]
    grades = []
    for score in scores:
        for threshold, grade in mapping:
            if score >= threshold:
                grades.append(grade)
                break
    return grades

