class GradeLookup:
    def __init__(self, thresholds):
        self.thresholds = sorted(thresholds, key=lambda x: x[0], reverse=True)
        self.fallback = "F"

    def find_grade(self, score):
        for threshold, grade in self.thresholds:
            if score >= threshold:
                return grade
        return self.fallback

