def vectorize_grades(scores):
    grade_map = [
        (90, 'A'),
        (80, 'B'),
        (70, 'C'),
        (60, 'D'),
        (0, 'F')
    ]
    return [next(grade for threshold, grade in grade_map if score >= threshold) for score in scores]

