    result_a = policy.evaluate(95)
    result_b = policy.evaluate(85)
    result_c = policy.evaluate(75)
    result_d = policy.evaluate(65)
    result_f = policy.evaluate(50)
    print(result_a)
    print(result_b)
    print(result_c)
    print(result_d)
    print(result_f)

