def get_grade(score: int, thresholds: Dict[str, Tuple[int, int]]) -> str:
    grade_order = ["A", "B", "C", "D", "F"]
    for grade in grade_order:
        if grade in thresholds:
            min_score, max_score = thresholds[grade]
            if min_score <= score <= max_score:
                return grade
    return "F"

