from typing import final

@final
class LeapYearVerifier:

    @staticmethod
    def is_leap(year: int) -> bool:
        if year <= 0:
            return False
        if year % 4 != 0:
            return False
        if year % 100 != 0:
            return True
        if year % 400 != 0:
            return False
        return True
if __name__ == '__main__':
    verifier = LeapYearVerifier()
    test_years = [2000, 1900, 2024, 2023, 4, 100, 400, -5, 0]
    results = []
    for y in test_years:
        results.append(f'{y}: {verifier.is_leap(y)}')
    print('\n'.join(results))

def calculate_final_price(original_price: float, discount_percentage: float) -> float:
    if original_price < 0:
        raise ValueError("Original price cannot be negative")
    if discount_percentage < 0:
        raise ValueError("Discount percentage cannot be negative")
    if discount_percentage > 100:
        raise ValueError("Discount percentage cannot exceed 100")

    discount_amount = original_price * (discount_percentage / 100)
    final_price = original_price - discount_amount
    return round(final_price, 2)

if __name__ == '__main__':
    original = 100.0
    discount = 20.0
    result = calculate_final_price(original, discount)
    print(result)

