DISCOUNT_THRESHOLD = 100
HIGH_TIER_RATE = 0.10
LOW_TIER_RATE = 0.05

class PricingEngine:
    def __init__(self, base_threshold, high_rate, low_rate):
        self.base_threshold = base_threshold
        self.high_rate = high_rate
        self.low_rate = low_rate

    def apply_discount(self, price):
        if price > self.base_threshold:
            return price * (1 - self.high_rate)
        return price * (1 - self.low_rate)

if __name__ == '__main__':
    engine = PricingEngine(DISCOUNT_THRESHOLD, HIGH_TIER_RATE, LOW_TIER_RATE)
    print(engine.apply_discount(50))
    print(engine.apply_discount(150))

class ProductPricing:
    BASE_PRICE = 500
    DISCOUNT_PERCENT = 20

    def __init__(self, price, percent):
        self.price = price
        self.percent = percent

    def get_savings(self):
        return self.price * (self.percent / 100)

    def get_final_price(self):
        return self.price - self.get_savings()

    def process(self):
        savings = self.get_savings()
        final = self.get_final_price()
        return savings, final

if __name__ == '__main__':
    processor = ProductPricing(ProductPricing.BASE_PRICE, ProductPricing.DISCOUNT_PERCENT)
    saved, cost = processor.process()
    print(saved)
    print(cost)

