def validate_triangle(sides):
    if len(sides) != 3:
        return False
    for s in sides:
        if s <= 0:
            return False
    a, b, c = sides
    if (a + b) <= c:
        return False
    if (a + c) <= b:
        return False
    if (b + c) <= a:
        return False
    return True

