def check_voting_eligibility_bitwise(age, citizen, disenfranchised):
    status_flags = 0
    if age >= 18:
        status_flags |= 1
    if citizen:
        status_flags |= 2
    if not disenfranchised:
        status_flags |= 4
    return (status_flags & 7) == 7

