def validate_triangle(sides: Tuple[Union[int, float], Union[int, float], Union[int, float]]) -> bool:
    if len(sides) != 3:
        return False

    a, b, c = sides

    if a <= 0 or b <= 0 or c <= 0:
        return False

    if a + b <= c:
        return False
    if a + c <= b:
        return False
    if b + c <= a:
        return False

    return True

