def validate_triangle(a: float, b: float, c: float) -> Optional[str]:
    if a <= 0 or b <= 0 or c <= 0:
        return None
    if a + b <= c or a + c <= b or b + c <= a:
        return None
    if a == b and b == c:
        return "Equilateral"
    if a == b or b == c or a == c:
        return "Isosceles"
    return "Scalene"

