def check_triangle_validity(sides: List[Tuple[float, float, float]]) -> List[bool]:
    results = []
    for a, b, c in sides:
        if a <= 0 or b <= 0 or c <= 0:
            results.append(False)
            continue
        if (a + b > c) and (a + c > b) and (b + c > a):
            results.append(True)
        else:
            results.append(False)
    return results

