def check_valid_triangle_sets(sides_list):
    results = []
    for sides in sides_list:
        if len(sides) != 3:
            results.append(False)
            continue
        a, b, c = sides
        if a <= 0 or b <= 0 or c <= 0:
            results.append(False)
            continue
        if a + b > c and a + c > b and b + c > a:
            results.append(True)
        else:
            results.append(False)
    return results

