def count_vowels(text: str) -> int:
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    unique_chars = set(text)
    found_vowels = unique_chars.intersection(vowels)
    return len(found_vowels)

if __name__ == '__main__':
    sample_text = "Hello World"
    result = count_vowels(sample_text)
    print(result)

def count_vowels(text):
    vowels = set('aeiouAEIOU')
    unique_chars = set(text)
    common = unique_chars & vowels
    return sum(text.count(v) for v in common)

if __name__ == '__main__':
    sample_text = "Hello World"
    result = count_vowels(sample_text)
    print(result)

class VowelCounter:
    def __init__(self, text):
        self.text = text
        self.vowels = set('aeiou')

    def count(self):
        return sum(1 for char in self.text.lower() if char in self.vowels)

if __name__ == '__main__':
    counter = VowelCounter("Rhythm is a part of life")
    print(counter.count())
    counter2 = VowelCounter("AEIOU")
    print(counter2.count())
    counter3 = VowelCounter("bcdfg")
    print(counter3.count())

