class VowelCounter:
    VOWEL_SET = frozenset("aeiouAEIOU")

    def __init__(self, text):
        self.text = text

    def get_vowel_count(self):
        count = 0
        for char in self.text:
            if char in self.VOWEL_SET:
                count += 1
        return count

def count_vowels(text):
    counter = VowelCounter(text)
    return counter.get_vowel_count()

