import sys

VOWELS = set('aeiouAEIOU')

def build_translation_map():
    mapping = {chr(i): 0 for i in range(sys.maxunicode + 1)}
    for char in VOWELS:
        mapping[char] = 1
    return mapping

TRANSLATION_MAP = build_translation_map()

def count_vowels_optimized(text):
    total = 0
    for char in text:
        total += TRANSLATION_MAP.get(char, 0)
    return total

