class MaxFinder:
    def __init__(self, v1, v2, v3):
        self.v1 = v1
        self.v2 = v2
        self.v3 = v3

    def get_max(self):
        return self.v1 if self.v1 >= self.v2 and self.v1 >= self.v3 else (self.v2 if self.v2 >= self.v3 else self.v3)

    def get_values(self):
        return self.v1, self.v2, self.v3

if __name__ == '__main__':
    a = 8
    b = 42
    c = 19
    finder = MaxFinder(a, b, c)
    values = finder.get_values()
    largest = finder.get_max()
    print(values)
    print(largest)

class NumberComparator:
    MAX_VALUE_THRESHOLD = 0

    @staticmethod
    def _determine_max(x, y):
        return x if x > y else y

    @classmethod
    def get_highest(cls, first, second, third):
        pair_max = cls._determine_max(first, second)
        return cls._determine_max(pair_max, third)

if __name__ == '__main__':
    val_one = 42
    val_two = 17
    val_three = 99
    computed_result = NumberComparator.get_highest(val_one, val_two, val_three)
